const cmds = [
  ["instructions", "pwd && rg --files -g 'AGENTS.md' -g '!node_modules' -g '!dist' -g '!build' | sort && printf '\\n-- phase README --\\n' && sed -n '1,260p' docs/prompts/implementation-phases/README.md", 30000],
  ["git", "git status --short --branch && git rev-parse --show-toplevel && git branch --show-current && git rev-parse HEAD && git log -8 --oneline --decorate", 12000],
  ["entire", "entire agent-help", 20000],
  ["files", "rg --files -g '!node_modules' -g '!dist' -g '!build' | sort", 30000],
  ["manifests", "for f in package.json package-lock.json npm-shrinkwrap.json pnpm-lock.yaml yarn.lock bun.lockb tsconfig.json vite.config.* vitest.config.* render.yaml Dockerfile .nvmrc .node-version .tool-versions; do if [ -f \"$f\" ]; then printf '\\n-- %s --\\n' \"$f\"; sed -n '1,260p' \"$f\"; fi; done", 40000]
];
const rs = await Promise.all(cmds.map(async ([name,cmd,max]) => [name, await tools.exec_command({cmd,workdir:"/home/kernel-kain/Documents/Github/unfinished-business",yield_time_ms:10000,max_output_tokens:max})]));
for (const [name,r] of rs) { text(`\n===== ${name} =====\n${r.output}`); }

