-- vite.config.ts --
import { sentryVitePlugin } from "@sentry/bundler-plugins/vite";
import react from "@vitejs/plugin-react";
import { defineConfig, loadEnv } from "vite";

export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, process.cwd(), "");
  const authToken = REDACTED;
  const renderCommit = env.RENDER_GIT_COMMIT?.trim();
  const renderRepository = env.RENDER_GIT_REPO_SLUG?.trim();
  const releaseName = env.SENTRY_RELEASE?.trim()
    || (renderCommit ? `unfinished-business@${renderCommit}` : undefined);
  const deployEnvironment = env.SENTRY_DEPLOY_ENVIRONMENT?.trim();
  if (env.RENDER && !authToken) {
    throw new Error("SENTRY_AUTH_TOKEN is required for Render builds so deployed source maps are uploaded.");
  }
  if (authToken && !releaseName) {
    throw new Error("SENTRY_RELEASE is required when SENTRY_AUTH_TOKEN is set so events and source maps use the same release.");
  }
  const uploadSourceMaps = Boolean(authToken && releaseName);

  return {
    plugins: [
      react(),
      ...(releaseName ? [sentryVitePlugin({
        org: env.SENTRY_ORG || "kernelkain",
        project: env.SENTRY_PROJECT || "unfinished-business-web",
        authToken,
        url: env.SENTRY_URL || undefined,
        telemetry: false,
        errorHandler: (error) => {
          throw error;
        },
        sourcemaps: uploadSourceMaps
          ? { filesToDeleteAfterUpload: ["./dist/web/**/*.map"] }
          : { disable: true },
        release: {
          name: releaseName,
          create: uploadSourceMaps,
          finalize: uploadSourceMaps,
          setCommits: uploadSourceMaps
            ? (renderCommit && renderRepository
                ? { repo: renderRepository, commit: renderCommit }
                : { auto: true, ignoreMissing: true })
            : false,
          deploy: uploadSourceMaps && deployEnvironment ? { env: deployEnvironment } : false,
        },
      })] : []),
    ],
    build: {
      outDir: "dist/web",
      emptyOutDir: true,
      sourcemap: uploadSourceMaps ? "hidden" : false,
    },
    server: {
      host: "127.0.0.1",
      port: 5173,
      proxy: {
        "/api": `http://127.0.0.1:${env.UB_PORT || "4200"}`,
      },
    },
  };
});

-- render.yaml --
services:
  - type: web
    name: unfinished-business
    runtime: node
    region: singapore
    plan: 0.5c-512mb
    autoDeployTrigger: checksPass
    buildCommand: npm ci && npm run typecheck && npm test && npm run build
    startCommand: npm run start:render
    healthCheckPath: /api/health
    envVars:
      - key: NODE_VERSION
        value: 22.14.0
      - key: UB_HOST
        value: 0.0.0.0
      - key: UB_DATA_DIR
        value: /var/data/unfinished-business
      - key: UB_ACCESS_USERNAME
        value: unfinished-business
      - key: UB_ACCESS_PASSWORD
        generateValue: true
      - key: UB_SESSION_TOKEN
        generateValue: true
      - key: OPENCODE_BASE_URL
        value: http://127.0.0.1:4096
      - key: OPENCODE_PASSWORD
        generateValue: true
      - key: OPENCODE_DATA_HOME
        value: /var/data/xdg-data
      - key: OPENCODE_CONFIG_HOME
        value: /var/data/xdg-config
      - key: SENTRY_DSN
        sync: false
      - key: SENTRY_ENVIRONMENT
        value: production
      - key: SENTRY_TRACES_SAMPLE_RATE
        value: "0.1"
      - key: SENTRY_AGENT_TRACES_SAMPLE_RATE
        value: "1"
      - key: SENTRY_PROFILES_SAMPLE_RATE
        value: "0.1"
      - key: VITE_SENTRY_DSN
        sync: false
      - key: VITE_SENTRY_ENVIRONMENT
        value: production
      - key: VITE_SENTRY_TRACES_SAMPLE_RATE
        value: "0.1"
      - key: VITE_SENTRY_REPLAYS_SESSION_SAMPLE_RATE
        value: "0.1"
      - key: VITE_SENTRY_REPLAYS_ON_ERROR_SAMPLE_RATE
        value: "1"
      - key: SENTRY_AUTH_TOKEN
        sync: false
      - key: SENTRY_ORG
        value: kernelkain
      - key: SENTRY_PROJECT
        value: unfinished-business-web
      - key: SENTRY_URL
        value: https://de.sentry.io
      - key: SENTRY_DEPLOY_ENVIRONMENT
        value: production
    disk:
      name: unfinished-business-data
      mountPath: /var/data
      sizeGB: 1

