===== .opencode/plugin/entire.ts =====
// Entire CLI plugin for OpenCode
// Auto-generated by `entire enable --agent opencode`
// Do not edit manually — changes will be overwritten on next install.
//
// Uses node:child_process so hooks work under both Bun (OpenCode CLI/TUI)
// and Node (OpenCode Desktop's Electron sidecar). See #2014.
//
// One file serves both plugin APIs, through its only export. The two
// loaders cannot share a shape: OpenCode 1 before v1.3 calls every export as
// a function (an object export crashes OpenCode), and OpenCode 2 requires the
// default export to be an {id, setup} object. So the default export is chosen
// when the module loads: OpenCode 1 sets OPENCODE=1 in its own environment
// and gets the plugin function; anything else gets {id, server, setup}
// (OpenCode 1.3+ also accepts that object, through `server`).
import { spawn, spawnSync } from "node:child_process"
import { readFileSync } from "node:fs"
import { fileURLToPath } from "node:url"
import type { Plugin } from "@opencode-ai/plugin"

/**
 * Build the shell command for a hook invocation.
 * Uses sh -c so the command is guarded by a `command -v` probe: when the
 * entire binary is not on PATH the hook exits 0 rather than failing the
 * surrounding OpenCode operation.
 */
function hookCmd(hookName: string): string[] {
  return ["sh", "-c", `if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks opencode ${hookName}`]
}

// parseInjectedContext scans a hook's stdout for Entire's injection envelope
// ({"inject_context":"..."}) and returns the text to inject, or null.
function parseInjectedContext(stdout: string): string | null {
  if (!stdout) return null
  for (const line of stdout.split("\n")) {
    const trimmed = line.trim()
    if (!trimmed.startsWith("{")) continue
    try {
      const parsed = JSON.parse(trimmed) as { inject_context?: unknown }
      if (typeof parsed.inject_context === "string" && parsed.inject_context.length > 0) {
        return parsed.inject_context
      }
    } catch {
      // not our envelope — ignore
    }
  }
  return null
}

// shadowedByLegacyCopy reports whether an Entire plugin an earlier CLI wrote
// to .opencode/plugins sits beside this one in .opencode/plugin. OpenCode 1.0.224+
// loads both directories, so on OpenCode 1 this copy stands down rather than
// fire every hook twice (a teammate on an older CLI can re-create the old file).
// OpenCode 2 cannot load the old copy, so its plugin never stands down.
// The old copy is looked up beside this file, not under the session
// directory: OpenCode finds .opencode by searching up from the directory it
// was started in, so that directory can be a subdirectory of the one holding
// both copies.
function shadowedByLegacyCopy(): boolean {
  try {
    if (!fileURLToPath(import.meta.url).replace(/\\/g, "/").includes("/.opencode/plugin/")) return false
    return readFileSync(new URL("../plugins/entire.ts", import.meta.url), "utf8").includes("entire enable --agent opencode")
  } catch {
    return false
  }
}

// OpenCode 1 plugin.
const EntirePlugin: Plugin = async ({ directory }) => {
  if (shadowedByLegacyCopy()) return {}
  // Track seen user messages to fire turn-start only once per message
  const seenUserMessages = new Set<string>()
  // Track current session ID for message events (which don't include sessionID)
  let currentSessionID: string | null = null
  // Track the model used by the most recent assistant message
  let currentModel: string | null = null
  // In-memory store for message metadata (role, tokens, etc.)
  const messageStore = new Map<string, any>()
  // One-time model-context injection captured from the turn-start hook's stdout,
  // applied on the next LLM call via experimental.chat.system.transform.
  let pendingInjection: string | null = null
  // Child (subagent) sessions. OpenCode's task tool runs each subagent as a
  // real session, so without this set a child would register as the user's
  // session: its write would take the checkpoint and the parent would log
  // "no files modified". Learned from session.* events' `parentID`, and from the child
  // ID surfaced in the parent's task part / tool.execute.after — the latter
  // two also cover a child session resumed via `task_id` from an earlier
  // process, whose own session.created predates this plugin instance. These
  // sets live for the process and are cleared only on server.instance.disposed.
  const childSessions = new Set<string>()
  // child session ID -> the top-level (user's) session it descends from. With
  // subagent_depth > 1 a child can itself call the task tool; that
  // grandchild's task is recorded on the top-level session, the only one
  // Entire tracks, keyed by its own callID like any other task.
  const rootOf = new Map<string, string>()
  // child session ID -> the session that launched it, so aborting a session
  // can end the background calls it launched.
  const parentOf = new Map<string, string>()
  // The per-call maps and sets below are keyed by callKey: the calling
  // session plus the hook key. A callID is unique only within one session
  // (some providers number calls per conversation), so a child's own task
  // call can share one with its parent's running call.
  // Call keys already announced via subagent-start (the running part update
  // repeats), so a late running update cannot announce a task again after its
  // stop. Cleared for a key when a new call starts under it (a reused callID).
  const announcedTasks = new Set<string>()
  // Call key -> Date.now() at tool.execute.before, sent as started_at. A
  // child resumed via `task_id` holds every earlier call's messages too; this
  // is what lets the CLI keep only the ones this call produced. The hook key
  // is the part's callID, except for a command subtask (`subtask: true`),
  // whose before/after hooks carry the task part's own id instead.
  const taskStartedAt = new Map<string, number>()
  // Announced tasks not yet stopped: call key -> its subagent-stop payload.
  // Every stop path takes the entry out, so a task stops at most once.
  const liveTasks = new Map<string, Record<string, unknown>>()
  // Call key of a task part id -> call key of its callID, to map a command
  // subtask's hook key to the callID its subagent-start used.
  const partCallID = new Map<string, string>()
  // Call keys whose stop fired before their running part was announced. The
  // late announcement is then skipped rather than opening a task that would
  // never stop.
  const stoppedBeforeStart = new Set<string>()
  // Call keys of tasks stopped from their error part, so a
  // tool.execute.after that still arrives does not stop them again.
  const stoppedOnError = new Set<string>()
  // Background children (OPENCODE_EXPERIMENTAL_BACKGROUND_SUBAGENTS, or a
  // foreground task promoted to the background): child ID -> subagent-stop
  // payloads held back until the child's own session goes idle. A queue: a
  // resume via `task_id` that joins a running child is queued behind the
  // current run and runs as its own busy -> idle cycle, so each idle ends the
  // oldest held call.
  const backgroundTasks = new Map<string, Record<string, unknown>[]>()
  // Sessions whose last session.status was not idle. An idle only ends a
  // held call when it follows a busy period: an errored run reports idle
  // twice.
  const busySessions = new Set<string>()
  // Children whose held stops all end at their next idle: an abort reached
  // them mid-run. Cancelling a job does not cancel a joined run already
  // executing, so the child's own idle, not the abort, is when it ends.
  const drainAtIdle = new Set<string>()

  /**
   * Pipe JSON payload to an entire hooks command (async).
   * Errors are logged but never thrown — plugin failures must not crash OpenCode.
   */
  async function callHook(hookName: string, payload: Record<string, unknown>) {
    try {
      const json = JSON.stringify(payload)
      const [cmd, ...args] = hookCmd(hookName)
      await new Promise<void>((resolve) => {
        const proc = spawn(cmd, args, {
          cwd: directory,
          stdio: ["pipe", "ignore", "ignore"],
        })
        proc.on("error", () => resolve())
        proc.on("close", () => resolve())
        proc.stdin?.end(json + "\n")
      })
    } catch {
      // Silently ignore — plugin failures must not crash OpenCode
    }
  }

  /**
   * Synchronous variant for hooks that must complete before subsequent agent work
   * or process exit. `turn-start` must finish initializing session state before a
   * fast mid-turn commit can hit git hooks, and `turn-end` / `session-end` must
   * finish before `opencode run` tears down its event loop.
   */
  function callHookSync(hookName: string, payload: Record<string, unknown>) {
    try {
      const json = JSON.stringify(payload)
      const [cmd, ...args] = hookCmd(hookName)
      spawnSync(cmd, args, {
        cwd: directory,
        input: json + "\n",
        stdio: ["pipe", "ignore", "ignore"],
      })
    } catch {
      // Silently ignore — plugin failures must not crash OpenCode
    }
  }

  // fireTurnStart fires turn-start synchronously (state must be ready before
  // mid-turn commits) and stashes any model-context injection emitted on stdout
  // for experimental.chat.system.transform to apply. Entire emits the injection
  // at most once per session, so pendingInjection is set on the first turn only.
  function fireTurnStart(payload: Record<string, unknown>) {
    try {
      const json = JSON.stringify(payload)
      const [cmd, ...args] = hookCmd("turn-start")
      const proc = spawnSync(cmd, args, {
        cwd: directory,
        input: json + "\n",
        encoding: "utf8",
        stdio: ["pipe", "pipe", "ignore"],
      })
      const out = typeof proc.stdout === "string" ? proc.stdout : ""
      const injected = parseInjectedContext(out)
      if (injected) pendingInjection = injected
    } catch {
      // Silently ignore — plugin failures must not crash OpenCode
    }
  }

  // trackChild records a child and the top-level session it descends from.
  function trackChild(childID: string, parentID: string) {
    childSessions.add(childID)
    if (!rootOf.has(childID)) rootOf.set(childID, rootOf.get(parentID) ?? parentID)
    if (!parentOf.has(childID)) parentOf.set(childID, parentID)
  }

  // callKey scopes a hook key (a callID or a task part id) to the session
