      partCallID.delete(partKey)
      stoppedBeforeStart.delete(partKey)
    }
    if (!payload) return
    stoppedOnError.add(key)
    if (part.id) stoppedOnError.add(partKey)
    callHookSync("subagent-stop", payload)

