  });
  assert.equal(denied.status, 409);
  const witness = await app.request("/api/messages", {
    method: "POST",
    headers,
    body: JSON.stringify({ actionId: "review", expectedRevision: 0, intent: "witness", text: "Review the evidence." }),
  });
