428	    throw new ExperienceFailure(
429	      saved.project.operations.at(-1)?.result ?? message,
430	      uncertain ? "NATIVE_UNKNOWN" : "NATIVE_FAILED",
431	      uncertain ? 503 : 502,
432	      !uncertain,
433	      saved.project.operations.at(-1)?.id ?? null,
434	    );
435	  }
436	}
437	
438	function sessionFor(project: Project, role: SpiritRole): string | null {
439	  return project.nativeSessions.find((item) => item.role === role)?.sessionId ?? null;
440	}
441	
442	function operation(
443	  kind: Project["operations"][number]["kind"],
444	  payload: object,
445	  spoken: { sessionId: string; messageId: string | null },
446	  result: string,
447	): Project["operations"][number] {
448	  return {
449	    id: randomUUID(),
450	    kind,
451	    payloadHash: payloadHash(payload),
452	    nativeSessionId: spoken.sessionId,
453	    nativeMessageId: spoken.messageId,
454	    status: "SUCCEEDED",
455	    result,
456	  };
457	}

