  1	import { randomUUID } from "node:crypto";
  2	import { payloadHash, refreshNextAction, type Project, type SpiritRole } from "../workflow/model.ts";
  3	import { AtomicProjectStore, RevisionConflict } from "../store/atomic-project-store.ts";
  4	import { loadStagePrompt, type Stage } from "../prompts/loader.ts";
  5	import { WorkflowService } from "../workflow/service.ts";
  6	import {
  7	  approveProduct,
  8	  grantMakerScope,
  9	  recordOracleProposal,
 10	  recordWitnessDrafts,
 11	  rememberSession,
 12	  rememberTranscript,
 13	  reviseSection,
 14	  WorkflowConflict,
 15	} from "../workflow/transitions.ts";
 16	import type { SpiritGuide } from "./guide.ts";
 17	import { runApprovedNodeCheck } from "./node-check.ts";
 18	import {
 19	  extractJsonObject,
 20	  formatSectionDraft,
 21	  oracleReplySchema,
 22	  sectionReplySchema,
 23	  witnessReplySchema,
 24	} from "./parse.ts";
 25	import { traceAgentOperation, traceToolOperation } from "./telemetry.ts";
 26	
 27	export class ExperienceFailure extends Error {
 28	  constructor(
 29	    message: string,
 30	    readonly code: string,
 31	    readonly status: number,
 32	    readonly retryable: boolean,
 33	    readonly operationId: string | null = null,
 34	  ) {
 35	    super(message);
 36	  }
 37	}
 38	
 39	interface Claimed {
 40	  project: Project;
 41	  duplicate: boolean;
 42	}
 43	
 44	const stagePrompt: Record<"oracle" | "architect" | "witness", Stage> = {
 45	  oracle: "oracle",
 46	  architect: "architect",
 47	  witness: "witness",
 48	};
 49	
 50	export class ExperienceService {
 51	  constructor(
 52	    private readonly workflow: WorkflowService,
 53	    private readonly store: AtomicProjectStore,
 54	    private readonly guide: SpiritGuide,
 55	    private readonly options: { safeDirectory: string; demoWorkspace: string; promptRoot?: string },
 56	  ) {}
 57	
 58	  async sendMessage(actionId: string, expectedRevision: number, intent: "clarify" | "draft" | "question" | "witness", text: string) {
 59	    const payload = { intent, text };
 60	    const claimed = await this.claim(actionId, payload, expectedRevision);
 61	    if (claimed.duplicate) return { project: claimed.project, duplicate: true };
 62	    const project = claimed.project;
 63	    try {
 64	      if (intent === "clarify") return await this.clarify(actionId, payload, expectedRevision, project, text);
 65	      if (intent === "draft") return await this.draft(actionId, payload, expectedRevision, project, text);
 66	      if (intent === "question") return await this.question(actionId, payload, expectedRevision, project, text);
 67	      return await this.witness(actionId, payload, expectedRevision, project, text);
 68	    } catch (error) {
 69	      if (error instanceof ExperienceFailure || error instanceof WorkflowConflict || error instanceof RevisionConflict) throw error;
 70	      return this.recordUncertain(actionId, payload, expectedRevision, intent, error);
 71	    }
 72	  }
 73	
 74	  async approve(actionId: string, expectedRevision: number, kind: "product" | "maker-scope", statement?: string) {
 75	    const payload = { kind, statement: statement ?? null };
 76	    return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
 77	      if (kind === "product") return approveProduct(project);
 78	      return grantMakerScope(project, statement ?? "");
 79	    });
 80	  }
 81	
 82	  async runMaker(actionId: string, expectedRevision: number) {
 83	    const payload = { intent: "maker" };
 84	    const claimed = await this.claim(actionId, payload, expectedRevision);
 85	    if (claimed.duplicate) return { project: claimed.project, duplicate: true };
 86	    const project = claimed.project;
 87	    if (project.makerScope.status !== "GRANTED" || !project.makerScope.statement) {
 88	      throw new ExperienceFailure("Grant a separate Maker scope before a native run.", "MAKER_SCOPE_REQUIRED", 409, false);
 89	    }
 90	    const makerScope = project.makerScope.statement;
 91	    return traceAgentOperation("maker", project.id, async () => {
 92	      const prompt = await this.instructions("maker", project, makerScope);
 93	      let performed;
 94	      try {
 95	        performed = await this.guide.perform({
 96	          conversationId: project.id,
 97	          sessionId: sessionFor(project, "maker"),
 98	          prompt,
 99	          workspace: this.options.demoWorkspace,
100	        });
101	      } catch (error) {
102	        return this.recordUncertain(actionId, payload, expectedRevision, "maker", error);
103	      }
104	      const edited = !performed.diff.includes("without a file diff");
105	      const check = edited
106	        ? await traceToolOperation("maker", project.id, "node.test", () => runApprovedNodeCheck(this.options.demoWorkspace))
107	        : null;
108	      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
109	        const next = structuredClone(current);
110	        rememberSession(next, "maker", performed.sessionId);
111	        const checkText = check
112	          ? `Node check exit ${check.code ?? "unavailable"}. ${check.output}`
113	          : "No native diff, so the Node check did not run.";
114	        next.operations.push({
115	          id: randomUUID(),
116	          kind: "maker",
117	          payloadHash: payloadHash(payload),
118	          nativeSessionId: performed.sessionId,
119	          nativeMessageId: performed.messageId,
120	          status: edited ? "SUCCEEDED" : "FAILED",
121	          result: `${performed.diff}\n\n${checkText}`,
122	        });
123	        if (check) {
124	          next.evidence.push({
125	            id: randomUUID(),
126	            checkId: "CK-06",
127	            nativeResultReference: performed.sessionId,
128	            testedFingerprint: payloadHash(check.output),
129	            result: check.code === 0 ? "PASS" : "FAIL",
130	            observedAt: new Date().toISOString(),
131	            limitation: check.code === 0 ? null : "The native edit did not leave a passing Node test.",
132	          });
133	          const capability = next.capabilities.find((item) => item.id === "node-check");
134	          if (capability) {
135	            capability.availability = "available";
136	            capability.observedOutcome = check.code === 0 ? "PASS" : "FAIL";
137	          }
138	          const inspection = next.capabilities.find((item) => item.id === "inspect-changes");
139	          if (inspection) {
140	            inspection.availability = "available";
141	            inspection.observedOutcome = performed.diff;
142	          }
143	        }
144	        rememberTranscript(next, "maker", edited ? performed.diff : "Maker finished without a file change.");
145	        return refreshNextAction(next);
146	      });
147	    });
148	  }
149	
150	  async cancel(actionId: string, expectedRevision: number, operationId: string) {
151	    return this.workflow.execute(actionId, { operationId }, expectedRevision, (project) => {
152	      const next = structuredClone(project);
153	      const operation = next.operations.find((item) => item.id === operationId);
154	      if (!operation) throw new WorkflowConflict("That operation is not in this project.");
155	      if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status)) {
156	        throw new WorkflowConflict("A finished operation cannot be cancelled.");
157	      }
158	      operation.status = "CANCELLED";
159	      operation.result = "Cancelled before another native attempt.";
160	      return refreshNextAction(next);
161	    });
162	  }
163	
164	  async reconcile(actionId: string, expectedRevision: number, operationId: string) {
165	    const payload = { operationId, intent: "reconcile" };
166	    const claimed = await this.claim(actionId, payload, expectedRevision);
167	    if (claimed.duplicate) return { project: claimed.project, duplicate: true };
168	    const operation = claimed.project.operations.find((item) => item.id === operationId);
169	    if (!operation?.nativeSessionId) {
170	      throw new ExperienceFailure("This operation has no native session to reconcile.", "NOTHING_TO_RECONCILE", 409, false);
171	    }
172	    const role = operation.kind === "maker" ? "maker" : operation.kind === "witness" ? "witness" : "architect";
173	    const observed = await this.guide.inspect(operation.nativeSessionId, {
174	      conversationId: claimed.project.id,
175	      role,
176	    });
177	    return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
178	      const next = structuredClone(project);
179	      const current = next.operations.find((item) => item.id === operationId);
180	      if (!current) throw new WorkflowConflict("That operation is not in this project.");
181	      if (observed === "running") {
182	        current.status = "RUNNING";
183	        current.result = "Native session is still running. It was not started again.";
184	      } else if (observed === "succeeded") {
185	        current.status = "SUCCEEDED";
186	        current.result = "Reconciled from the native session outcome.";
187	      } else if (observed === "failed") {
188	        current.status = "FAILED";
189	        current.result = "Reconciled from a failed or interrupted native session.";
190	      } else {
191	        current.status = "UNKNOWN";
192	        current.result = "Native outcome is still unknown. This action was not repeated.";
193	      }
194	      return refreshNextAction(next);
195	    });
196	  }
197	
198	  async exportApproved() {
199	    const project = await this.workflow.get();
200	    const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
201	    const plan = unresolved.length
202	      ? null
203	      : project.sections
204	        .toSorted((left, right) => left.order - right.order)
205	        .map((section) => `## ${section.title}\n\n${section.content}`)
206	        .join("\n\n");
207	    return {
208	      plan,
209	      unresolved: unresolved.map((section) => section.id),
210	      drafts: project.witnessDrafts.map((draft) => ({ title: draft.title, content: draft.content })),
211	      limitation: "Witness drafts are in-app review notes. They are not a submitted article, video, or entry.",
212	    };
213	  }
214	
215	  private async clarify(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
216	    return traceAgentOperation("oracle", project.id, async () => {
217	      if (project.product.status === "APPROVED") {
218	        throw new ExperienceFailure("The product proposal is already approved.", "PRODUCT_ALREADY_APPROVED", 409, false);
219	      }
220	      const spoken = await this.guide.speak({
221	        role: "oracle",
222	        conversationId: project.id,
223	        sessionId: sessionFor(project, "oracle"),
224	        prompt: await this.instructions("oracle", project, text),
225	        workspace: this.options.safeDirectory,
226	      });
227	      const reply = oracleReplySchema.parse(extractJsonObject(spoken.text));
228	      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
229	        const seeded = structuredClone(current);
230	        rememberTranscript(seeded, "user", text);
231	        const next = recordOracleProposal(seeded, { ...reply, sessionId: spoken.sessionId });
232	        next.operations.push(operation("guide", payload, spoken, "Oracle proposal stored. It is not approved."));
233	        return refreshNextAction(next);
234	      });
235	    });
236	  }
237	
238	  private async draft(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
239	    return traceAgentOperation("architect", project.id, async () => {
240	      if (project.product.status !== "APPROVED" || !project.currentSectionId) {
241	        throw new ExperienceFailure("Drafting waits for an approved product and an active section.", "SECTION_NOT_READY", 409, false);
242	      }
243	      const sectionId = project.currentSectionId;
244	      const spoken = await this.guide.speak({
245	        role: "architect",
246	        conversationId: project.id,
247	        sessionId: sessionFor(project, "architect"),
248	        prompt: await this.instructions("architect", project, text),
249	        workspace: this.options.safeDirectory,
250	      });
251	      let reply;
252	      try {
253	        reply = sectionReplySchema.parse(extractJsonObject(spoken.text));
254	      } catch {
255	        const prose = spoken.text.trim();
256	        if (prose.length < 80) {
257	          return this.recordFailure(actionId, payload, expectedRevision, "architect", spoken.sessionId, `The Architect reply was malformed, so the section was left unchanged. Reply began: ${prose.slice(0, 240)}`);
258	        }
259	        reply = {
260	          content: prose.slice(0, 12_000),
261	          recommendation: "The Architect returned prose. Review the draft before approval.",
262	          tradeoff: "Separate recommendation and tradeoff fields were not returned.",
263	        };
264	      }
265	      const content = formatSectionDraft(reply);
266	      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
267	        const next = reviseSection(current, sectionId, content);
268	        rememberSession(next, "architect", spoken.sessionId);
269	        rememberTranscript(next, "user", text);
270	        rememberTranscript(next, "architect", content);
271	        next.operations.push(operation("guide", payload, spoken, "Draft stored as the current section version."));
272	        return refreshNextAction(next);
273	      });
274	    });
275	  }
276	
277	  private async question(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
278	    const role = project.stage === "ORACLE" ? "oracle" : "architect";
279	    return traceAgentOperation(role, project.id, async () => {
280	      const spoken = await this.guide.speak({
281	        role,
282	        conversationId: project.id,
283	        sessionId: sessionFor(project, role),
284	        prompt: await this.instructions(role, project, `The user is asking a question. This is not approval and must not change an approved artifact.\n\n${text}`),
285	        workspace: this.options.safeDirectory,
286	      });
287	      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
288	        const next = structuredClone(current);
289	        rememberSession(next, role, spoken.sessionId);
290	        rememberTranscript(next, "user", text);
291	        rememberTranscript(next, role, spoken.text.slice(0, 4_000));
292	        next.operations.push(operation("guide", payload, spoken, "Question answered without changing approvals."));
293	        return refreshNextAction(next);
294	      });
295	    });
296	  }
297	
298	  private async witness(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
299	    return traceAgentOperation("witness", project.id, async () => {
300	      const makerDone = project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED");
301	      if (!makerDone) throw new ExperienceFailure("Witness review waits for a completed Maker run.", "WITNESS_NOT_READY", 409, false);
302	      const spoken = await this.guide.speak({
303	        role: "witness",
304	        conversationId: project.id,
305	        sessionId: null,
306	        prompt: await this.instructions("witness", project, text),
307	        workspace: this.options.safeDirectory,
308	      });
309	      let reply;
310	      try {
311	        reply = witnessReplySchema.parse(extractJsonObject(spoken.text));
312	      } catch {
313	        const prose = spoken.text.trim();
314	        if (prose.length < 80) {
315	          return this.recordFailure(actionId, payload, expectedRevision, "witness", spoken.sessionId, `The Witness reply was malformed, so no draft was stored. Reply began: ${prose.slice(0, 240)}`);
316	        }
317	        reply = {
318	          findings: prose.slice(0, 8_000),
319	          limitations: "The Witness returned prose rather than separate fields.",
320	          draftNotes: "These notes are an in-app review. They are not a submitted article or video.",
321	        };
322	      }
323	      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
324	        const next = recordWitnessDrafts(current, [
325	          { title: "Findings", content: reply.findings },
326	          { title: "Limitations", content: reply.limitations },
327	          { title: "Draft notes", content: reply.draftNotes },
328	        ], spoken.sessionId);
329	        next.operations.push(operation("witness", payload, spoken, "Witness drafts stored from a fresh session."));
330	        return refreshNextAction(next);
331	      });
332	    });
333	  }
334	
335	  private async instructions(role: "oracle" | "architect" | "maker" | "witness", project: Project, text: string): Promise<string> {
336	    const procedure = await loadStagePrompt(role === "maker" ? "maker" : stagePrompt[role], this.options.promptRoot);
337	    const section = project.sections.find((item) => item.id === project.currentSectionId);
338	    const shape = role === "oracle"
339	      ? '{"clarification":"...","proposal":"...","openQuestions":["..."]}'
340	      : role === "architect"
341	        ? '{"content":"...","recommendation":"...","tradeoff":"..."}'
342	        : role === "witness"
343	          ? '{"findings":"...","limitations":"...","draftNotes":"..."}'
344	          : "a code change, not JSON";
345	    return [
346	      procedure,
347	      "",
348	      "Current workshop state:",
349	      `stage ${project.stage}; product ${project.product.status}; next ${project.nextAction}`,
350	      section ? `active section ${section.order}. ${section.title}; version ${section.version}; status ${section.status}` : "no active section",
351	      project.product.proposal ? `approved-or-proposed product:\n${project.product.proposal}` : "no product proposal yet",
352	      project.evidence.length ? `observed checks:\n${project.evidence.map((item) => `${item.checkId} ${item.result}. ${item.limitation ?? ""}`).join("\n")}` : "no observed checks yet",
353	      project.operations.some((item) => item.kind === "maker")
354	        ? `maker results:\n${project.operations.filter((item) => item.kind === "maker").map((item) => item.result ?? item.status).join("\n")}`
355	        : "no maker result yet",
356	      "The spirit session directory is empty on purpose. Do not treat it as the demo workspace, and do not claim files are missing when a maker result or check is listed above.",
357	      "",
358	      "User message:",
359	      text,
360	      "",
361	      role === "maker"
362	        ? "The session directory is an isolated demo workspace. Implement the approved plan and Maker scope there as a dependency-free Node module plus a node:test file. Do not edit the Unfinished Business repository, do not run shell commands, and do not claim a test passed."
363	        : `Reply with one JSON object only, matching ${shape}. Do not approve, advance, or claim the user approved. A question is not approval.`,
364	    ].join("\n");
365	  }
366	
367	  private async claim(actionId: string, payload: object, expectedRevision: number): Promise<Claimed> {
368	    const loaded = await this.store.load();
369	    const hash = payloadHash(payload);
370	    const existing = loaded.state.actions.find((action) => action.id === actionId);
371	    if (existing) {
372	      if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
373	      return { project: loaded.state, duplicate: true };
374	    }
375	    if (loaded.state.revision !== expectedRevision) {
376	      throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
377	    }
378	    return { project: loaded.state, duplicate: false };
379	  }
380	
381	  private async recordFailure(
382	    actionId: string,
383	    payload: object,
384	    expectedRevision: number,
385	    role: SpiritRole,
386	    sessionId: string | null,
387	    message: string,
388	  ) {
389	    const saved = await this.workflow.execute(actionId, payload, expectedRevision, (project) => {
390	      const next = structuredClone(project);
391	      const operationId = randomUUID();
392	      next.operations.push({
393	        id: operationId,
394	        kind: role === "witness" ? "witness" : "guide",
395	        payloadHash: payloadHash(payload),
396	        nativeSessionId: sessionId,
397	        nativeMessageId: null,
398	        status: "FAILED",
399	        result: message,
400	      });
401	      rememberTranscript(next, "system", message);
402	      return refreshNextAction(next);
403	    });
404	    throw new ExperienceFailure(message, "MALFORMED_RESPONSE", 400, true, saved.project.operations.at(-1)?.id ?? null);
405	  }
406	
407	  private async recordUncertain(actionId: string, payload: object, expectedRevision: number, intent: string, error: unknown) {
408	    const message = error instanceof Error ? error.message : "The native spirit could not be reached.";
409	    const uncertain = /timed out|ECONN|fetch|network|socket|unavailable/i.test(message);
410	    const saved = await this.workflow.execute(actionId, payload, expectedRevision, (project) => {
411	      const next = structuredClone(project);
412	      next.operations.push({
413	        id: randomUUID(),
414	        kind: intent === "maker" ? "maker" : intent === "witness" ? "witness" : "guide",
415	        payloadHash: payloadHash(payload),
416	        nativeSessionId: null,
417	        nativeMessageId: null,
418	        status: uncertain ? "UNKNOWN" : "FAILED",
419	        result: uncertain
420	          ? "Disconnected or timed out. Reconcile the native session before any new run."
421	          : message,
422	      });
423	      rememberTranscript(next, "system", uncertain
424	        ? "The native run is unknown. It was not repeated."
425	        : message);
426	      return refreshNextAction(next);
427	    });
428	    throw new ExperienceFailure(
429	      saved.project.operations.at(-1)?.result ?? message,
430	      uncertain ? "NATIVE_UNKNOWN" : "NATIVE_FAILED",
431	      uncertain ? 503 : 502,
432	      !uncertain,
433	      saved.project.operations.at(-1)?.id ?? null,
434	    );
435	  }
436	}
437	
438	function sessionFor(project: Project, role: SpiritRole): string | null {
439	  return project.nativeSessions.find((item) => item.role === role)?.sessionId ?? null;
440	}
441	
442	function operation(
443	  kind: Project["operations"][number]["kind"],
444	  payload: object,
445	  spoken: { sessionId: string; messageId: string | null },
446	  result: string,
447	): Project["operations"][number] {
448	  return {
449	    id: randomUUID(),
450	    kind,
451	    payloadHash: payloadHash(payload),
452	    nativeSessionId: spoken.sessionId,
453	    nativeMessageId: spoken.messageId,
454	    status: "SUCCEEDED",
455	    result,
456	  };
457	}

