 82	  async runMaker(actionId: string, expectedRevision: number) {
 83	    const payload = { intent: "maker" };
 84	    const claimed = await this.claim(actionId, payload, expectedRevision);
 85	    if (claimed.duplicate) return { project: claimed.project, duplicate: true };
 86	    const project = claimed.project;
 87	    if (project.makerScope.status !== "GRANTED" || !project.makerScope.statement) {
 88	      throw new ExperienceFailure("Grant a separate Maker scope before a native run.", "MAKER_SCOPE_REQUIRED", 409, false);
 89	    }
 90	    const makerScope = project.makerScope.statement;
 91	    return traceAgentOperation("maker", project.id, async () => {
 92	      const prompt = await this.instructions("maker", project, makerScope);
 93	      let performed;
 94	      try {
 95	        performed = await this.guide.perform({
 96	          conversationId: project.id,
 97	          sessionId: sessionFor(project, "maker"),
 98	          prompt,
 99	          workspace: this.options.demoWorkspace,
100	        });
101	      } catch (error) {
102	        return this.recordUncertain(actionId, payload, expectedRevision, "maker", error);
103	      }
104	      const edited = !performed.diff.includes("without a file diff");
105	      const check = edited
106	        ? await traceToolOperation("maker", project.id, "node.test", () => runApprovedNodeCheck(this.options.demoWorkspace))
107	        : null;
108	      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
109	        const next = structuredClone(current);
110	        rememberSession(next, "maker", performed.sessionId);
111	        const checkText = check
112	          ? `Node check exit ${check.code ?? "unavailable"}. ${check.output}`
113	          : "No native diff, so the Node check did not run.";
114	        next.operations.push({
115	          id: randomUUID(),
116	          kind: "maker",
117	          payloadHash: payloadHash(payload),
118	          nativeSessionId: performed.sessionId,
119	          nativeMessageId: performed.messageId,
120	          status: edited ? "SUCCEEDED" : "FAILED",
121	          result: `${performed.diff}\n\n${checkText}`,
122	        });
123	        if (check) {
124	          next.evidence.push({
125	            id: randomUUID(),
126	            checkId: "CK-06",
127	            nativeResultReference: performed.sessionId,
128	            testedFingerprint: payloadHash(check.output),
129	            result: check.code === 0 ? "PASS" : "FAIL",
130	            observedAt: new Date().toISOString(),
131	            limitation: check.code === 0 ? null : "The native edit did not leave a passing Node test.",
132	          });
133	          const capability = next.capabilities.find((item) => item.id === "node-check");
134	          if (capability) {
135	            capability.availability = "available";
136	            capability.observedOutcome = check.code === 0 ? "PASS" : "FAIL";
137	          }
138	          const inspection = next.capabilities.find((item) => item.id === "inspect-changes");
139	          if (inspection) {
140	            inspection.availability = "available";
141	            inspection.observedOutcome = performed.diff;
142	          }
143	        }
144	        rememberTranscript(next, "maker", edited ? performed.diff : "Maker finished without a file change.");
145	        return refreshNextAction(next);
146	      });
147	    });
148	  }
