164	  async reconcile(actionId: string, expectedRevision: number, operationId: string) {
165	    const payload = { operationId, intent: "reconcile" };
166	    const claimed = await this.claim(actionId, payload, expectedRevision);
167	    if (claimed.duplicate) return { project: claimed.project, duplicate: true };
168	    const operation = claimed.project.operations.find((item) => item.id === operationId);
169	    if (!operation?.nativeSessionId) {
170	      throw new ExperienceFailure("This operation has no native session to reconcile.", "NOTHING_TO_RECONCILE", 409, false);
171	    }
172	    const role = operation.kind === "maker" ? "maker" : operation.kind === "witness" ? "witness" : "architect";
173	    const observed = await this.guide.inspect(operation.nativeSessionId, {
174	      conversationId: claimed.project.id,
175	      role,
176	    });
177	    return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
178	      const next = structuredClone(project);
179	      const current = next.operations.find((item) => item.id === operationId);
180	      if (!current) throw new WorkflowConflict("That operation is not in this project.");
181	      if (observed === "running") {
182	        current.status = "RUNNING";
183	        current.result = "Native session is still running. It was not started again.";
184	      } else if (observed === "succeeded") {
185	        current.status = "SUCCEEDED";
186	        current.result = "Reconciled from the native session outcome.";
187	      } else if (observed === "failed") {
188	        current.status = "FAILED";
189	        current.result = "Reconciled from a failed or interrupted native session.";
190	      } else {
191	        current.status = "UNKNOWN";
192	        current.result = "Native outcome is still unknown. This action was not repeated.";
193	      }
194	      return refreshNextAction(next);
195	    });
196	  }
