407	  private async recordUncertain(actionId: string, payload: object, expectedRevision: number, intent: string, error: unknown) {
408	    const message = error instanceof Error ? error.message : "The native spirit could not be reached.";
409	    const uncertain = /timed out|ECONN|fetch|network|socket|unavailable/i.test(message);
410	    const saved = await this.workflow.execute(actionId, payload, expectedRevision, (project) => {
411	      const next = structuredClone(project);
412	      next.operations.push({
413	        id: randomUUID(),
414	        kind: intent === "maker" ? "maker" : intent === "witness" ? "witness" : "guide",
415	        payloadHash: payloadHash(payload),
416	        nativeSessionId: null,
417	        nativeMessageId: null,
418	        status: uncertain ? "UNKNOWN" : "FAILED",
419	        result: uncertain
420	          ? "Disconnected or timed out. Reconcile the native session before any new run."
421	          : message,
422	      });
423	      rememberTranscript(next, "system", uncertain
424	        ? "The native run is unknown. It was not repeated."
425	        : message);
426	      return refreshNextAction(next);
427	    });
428	    throw new ExperienceFailure(
429	      saved.project.operations.at(-1)?.result ?? message,
430	      uncertain ? "NATIVE_UNKNOWN" : "NATIVE_FAILED",
431	      uncertain ? 503 : 502,
432	      !uncertain,
433	      saved.project.operations.at(-1)?.id ?? null,
434	    );
435	  }
