     9	function sampleRate(value: string | undefined, fallback: number): number {
    10	  if (value === undefined || value.trim() === "") return fallback;
    11	  const parsed = Number(value);
    12	  return Number.isFinite(parsed) && parsed >= 0 && parsed <= 1 ? parsed : fallback;
    13	}
