    90	    if (typeof body.available === "boolean") {
    91	      return {
    92	        available: body.available,
    93	        serverVersion: body.serverVersion ?? null,
    94	        modelAvailable: Boolean(body.modelAvailable),
    95	        limitation: body.limitation ?? null,
    96	      };
    97	    }
    98	  } catch {
    99	    // The status below is the visible recovery state.
   100	  }
   101	  return {
   102	    available: false,
   103	    serverVersion: null,
   104	    modelAvailable: false,
   105	    limitation: "OpenCode could not be reached from this workshop.",
   106	  };
   107	}
