    55	async function token(): Promise<string> {
    56	  if (sessionToken) return sessionToken;
    57	  const response = await fetch("/api/session");
    58	  if (!response.ok) throw new ApiError("The local workshop session could not be opened.", "SESSION", true);
    59	  const body = await response.json() as { token: string };
    60	  sessionToken = REDACTED;
    61	  return sessionToken;
