    64	async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
    65	  const headers: Record<string, string> = {};
    66	  if (init?.body) {
    67	    headers["content-type"] = "application/json";
    68	    headers["x-ub-session-token"] = await token();
    69	  }
    70	  const response = await fetch(path, {
    71	    method: init?.method ?? "GET",
    72	    headers,
    73	    body: init?.body ? JSON.stringify(init.body) : undefined,
    74	  });
    75	  const body = await response.json() as T & { message?: string; code?: string; retryable?: boolean };
    76	  if (!response.ok) {
    77	    throw new ApiError(body.message ?? "The workshop could not complete that action.", body.code ?? "REQUEST_FAILED", Boolean(body.retryable));
    78	  }
    79	  return body;
    80	}
