    21	async function command(binary, args, env = process.env) {
    22	  try {
    23	    const result = await execute(binary, args, {
    24	      cwd: workspace, env, timeout: 15_000, maxBuffer: 256 * 1024,
    25	    });
    26	    return { ok: true, output: result.stdout.trim() };
    27	  } catch (error) {
    28	    // Do not echo raw command output: providers/plugins may print secrets.
    29	    return { ok: false, code: error.killed ? 'TIMEOUT' : String(error.code ?? 'UNKNOWN') };
    30	  }
    31	}
