    33	async function locate(name) {
    34	  for (const directory of (process.env.PATH ?? '').split(delimiter)) {
    35	    if (!directory) continue;
    36	    const candidate = join(directory, name);
    37	    try {
    38	      await access(candidate, constants.X_OK);
    39	      return candidate;
    40	    } catch { /* Try the next PATH entry. */ }
    41	  }
    42	  return null;
    43	}
