    45	async function inspectOpenCode() {
    46	  const binary = await locate('opencode');
    47	  if (!binary) {
    48	    record('OPENCODE_CLI', 'FAIL', 'OpenCode is absent from PATH.');
    49	    return;
    50	  }
    51	  const temporary = await mkdtemp(join(tmpdir(), 'ub-preflight-'));
    52	  try {
    53	    // Supported disposable XDG storage avoids changing the user's sessions/auth.
    54	    const env = {
    55	      ...process.env,
    56	      XDG_DATA_HOME: join(temporary, 'data'),
    57	      XDG_CACHE_HOME: join(temporary, 'cache'),
    58	      XDG_STATE_HOME: join(temporary, 'state'),
    59	    };
    60	    const version = await command(binary, ['--version'], env);
    61	    const match = version.ok && version.output.match(/^opencode v?(\d+\.\d+\.\d+)(?:\s|$)/);
    62	    record('OPENCODE_CLI', match ? 'PASS' : 'INCONCLUSIVE', match
    63	      ? `Installed binary ${match[1]}; CLI startup only, not server/model proof.`
    64	      : 'Could not identify the binary version within 15 seconds.');
    65	    const help = await command(binary, ['serve', '--help'], env);
    66	    record('OPENCODE_SERVER_COMMAND', help.ok && /--hostname/.test(help.output) ? 'PASS' : 'INCONCLUSIVE',
    67	      'Inspects serve help only; no server or session was started.');
    68	    try {
    69	      const adjacent = join(dirname(dirname(binary)), 'node_modules', '@opencode-ai', 'sdk', 'package.json');
    70	      const sdk = JSON.parse(await readFile(adjacent, 'utf8'));
    71	      record('SDK_COMPATIBILITY', 'INCONCLUSIVE',
    72	        `Adjacent @opencode-ai/sdk ${sdk.version}; compatibility has not been exercised. Check the native v2 @opencode/client contract.`);
    73	    } catch {
    74	      record('SDK_COMPATIBILITY', 'NOT_RUN', 'No adjacent legacy SDK metadata found; select the supported version-matched client during EP-01.');
    75	    }
    76	  } finally {
    77	    await rm(temporary, { recursive: true, force: true });
    78	  }
    79	}
