    81	async function inspectNetwork(host) {
    82	  const resolver = new Resolver({ timeout: 1500, tries: 1 });
    83	  try {
    84	    await resolver.resolve4(host);
    85	    record(`DNS:${host}`, 'PASS', 'DNS resolves; HTTPS and authenticated/free inference remain unproven.');
    86	  } catch (error) {
    87	    record(`DNS:${host}`, 'FAIL', `DNS unavailable (${error.code ?? 'UNKNOWN'}).`);
    88	  } finally {
    89	    resolver.cancel();
    90	  }
    91	}
    92	
    93	async function inspectLoopback() {
    94	  await new Promise((done) => {
    95	    const server = createServer();
    96	    let completed = false;
    97	    const finish = (status, detail) => {
    98	      if (completed) return;
    99	      completed = true;
   100	      clearTimeout(timer);
   101	      record('LOOPBACK_BIND', status, detail);
   102	      done();
   103	    };
   104	    const timer = setTimeout(() => {
   105	      server.close(() => {});
   106	      finish('INCONCLUSIVE', 'Temporary localhost bind exceeded the two-second diagnostic bound.');
   107	    }, 2000);
   108	    server.once('error', (error) => finish('FAIL', `Cannot bind localhost (${error.code ?? 'UNKNOWN'}); native server proof cannot run here.`));
   109	    server.listen(0, '127.0.0.1', () => {
   110	      server.close(() => finish('PASS', 'Temporary localhost listener opened and closed; no requests, model calls or application server.'));
   111	    });
   112	  });
   113	}
   114	
   115	async function inspectRepository() {
   116	  const branch = await command('git', ['branch', '--show-current']);
   117	  const head = await command('git', ['rev-parse', '--short', 'HEAD']);
   118	  record('GIT_READ', branch.ok && head.ok ? 'PASS' : 'FAIL', branch.ok && head.ok
