   120	    : 'Cannot read current branch/HEAD.');
   121	  record('GIT_WRITE', 'NOT_RUN', 'No Git write probe. The agent session must separately permit .git writes before a phase commit.');
   122	}
   123	
   124	async function inspectEntire() {
   125	  const binary = await locate('entire');
   126	  if (!binary) {
   127	    record('ENTIRE_CAPTURE', 'FAIL', 'Entire is absent from PATH.');
   128	    return;
   129	  }
