   132	    record('ENTIRE_CAPTURE', 'FAIL', 'Entire reports capture is not enabled; no setup was performed.');
   133	  } else if (result.ok && /hooks?[^\n]*need approval/i.test(result.output)) {
   134	    record('ENTIRE_CAPTURE', 'FAIL', 'Entire is enabled, but agent hooks need approval. Open /hooks in the local Codex session, approve the Entire hooks, then verify capture.');
   135	  } else {
   136	    record('ENTIRE_CAPTURE', 'INCONCLUSIVE', 'Verify capture, sharing settings, supported agent and checkpoint evidence separately.');
   137	  }
   138	}
