   140	const [major, minor] = process.versions.node.split('.').map(Number);
   141	record('NODE', major > 22 || (major === 22 && minor >= 14) ? 'PASS' : 'FAIL', process.version);
   142	const tasks = await Promise.allSettled([
   143	  inspectOpenCode(), inspectRepository(), inspectEntire(),
   144	  inspectNetwork('opencode.ai'), inspectNetwork('registry.npmjs.org'), inspectLoopback(),
   145	]);
