   147	  if (result.status === 'rejected') record(`DIAGNOSTIC:${index}`, 'INCONCLUSIVE', 'Diagnostic failed; inspect the environment without exposing credentials.');
   148	}
   149	for (const name of ['SENTRY_DSN', 'BACKBOARD_API_KEY', 'OPENCODE_BASE_URL']) {
   150	  record(`ENV:${name}`, 'INFO', process.env[name] ? 'present (value withheld)' : 'absent from this process; other supported configuration locations not inspected');
   151	}
   152	for (const proof of ['EP-01_FREE_MODEL_AND_EDIT', 'EP-02_NATIVE_PERMISSIONS', 'EP-03_RECOVERY', 'EP-04_BACKBOARD', 'EP-05_SENTRY', 'EP-06_ENTIRE_CHECKPOINT']) {
   153	  record(proof, 'NOT_RUN', 'A diagnostic cannot establish this runtime proof.');
   154	}
   155	findings.sort((a, b) => a.id.localeCompare(b.id));
   156	const blocked = findings.some(({ status }) => status === 'FAIL');
   157	console.log(JSON.stringify({
   158	  status: blocked ? 'BLOCKED' : 'PREFLIGHT_ONLY',
   159	  workspace, findings,
   160	  limits: 'No inference, dependency installation, authentication changes, application server startup, capture setup, or Git writes. A temporary localhost listener is immediately closed. PASS refers only to the named diagnostic.',
   161	}, null, 2));
   162	process.exitCode = blocked ? 1 : 0;

