import type { MakerRun, RunEvent } from "./model.ts";

export type RunStreamItem =
  | { type: "snapshot"; run: MakerRun; events: RunEvent[]; resync: boolean }
  | { type: "event"; run: MakerRun; event: RunEvent }
  | { type: "heartbeat"; cursor: number };

interface Subscriber {
  after: number;
  push: (run: MakerRun, event: RunEvent) => void;
}

export class RunEventBroker {
  private readonly subscribers = new Map<string, Set<Subscriber>>();

  publish(run: MakerRun, event: RunEvent): void {
    for (const subscriber of this.subscribers.get(run.id) ?? []) {
      if (event.sequence > subscriber.after) {
        subscriber.after = event.sequence;
        subscriber.push(run, event);
      }
    }
  }

  async *stream(
    initial: MakerRun,
    requestedCursor: number | null,
    signal: AbortSignal,
    heartbeatMs = 15_000,
  ): AsyncGenerator<RunStreamItem> {
    const cursorValid = requestedCursor !== null
      && Number.isInteger(requestedCursor)
      && requestedCursor >= 0
      && requestedCursor <= initial.lastEventSequence;
    let cursor = cursorValid ? requestedCursor : 0;
    const pending = initial.events.filter((event) => event.sequence > cursor);
    if (!cursorValid && requestedCursor !== null) {
      yield { type: "snapshot", run: structuredClone(initial), events: structuredClone(initial.events), resync: true };
      cursor = initial.lastEventSequence;
    } else {
      for (const event of pending) {
        cursor = event.sequence;
        yield { type: "event", run: structuredClone(initial), event: structuredClone(event) };
      }
    }
    if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(initial.status)) return;

    const queue: Array<{ run: MakerRun; event: RunEvent }> = [];
    let wake: (() => void) | null = null;
    const subscriber: Subscriber = {
      after: cursor,
      push: (run, event) => {
        queue.push({ run: structuredClone(run), event: structuredClone(event) });
        wake?.();
      },
    };
    const set = this.subscribers.get(initial.id) ?? new Set<Subscriber>();
    set.add(subscriber);
    this.subscribers.set(initial.id, set);

    try {
      while (!signal.aborted) {
        if (!queue.length) {
          await new Promise<void>((resolve) => {
            wake = resolve;
            const timer = setTimeout(resolve, heartbeatMs);
            signal.addEventListener("abort", resolve, { once: true });
            const original = wake;
            wake = () => {
              clearTimeout(timer);
              original?.();
            };
          });
          wake = null;
        }
        if (signal.aborted) return;
        const item = queue.shift();
        if (!item) {
          yield { type: "heartbeat", cursor: subscriber.after };
          continue;
        }
        yield { type: "event", run: item.run, event: item.event };
        if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(item.run.status)) return;
      }
    } finally {
      set.delete(subscriber);
      if (!set.size) this.subscribers.delete(initial.id);
    }
  }
}

import { randomUUID } from "node:crypto";
import { z } from "zod";

export const runStatusSchema = z.enum([
  "QUEUED",
  "CONNECTING",
  "RUNNING",
  "WAITING_PERMISSION",
  "VERIFYING",
  "SUCCEEDED",
  "FAILED",
  "CANCELLED",
  "UNKNOWN",
]);

export const runEventCategorySchema = z.enum([
  "state",
  "session",
  "model",
  "tool",
  "permission",
  "files",
  "verification",
  "result",
  "recovery",
]);

const eventMetadataValueSchema = z.union([z.string(), z.number(), z.boolean(), z.null()]);

export const runEventSchema = z.object({
  version: z.literal(1),
  id: z.string(),
  sequence: z.number().int().positive(),
  timestamp: z.string(),
  category: runEventCategorySchema,
  summary: z.string().min(1).max(1_000),
  metadata: z.record(z.string(), eventMetadataValueSchema),
  evidenceRefs: z.array(z.string()),
});

export const runFileSchema = z.object({
  path: z.string(),
  status: z.enum(["added", "deleted", "modified"]),
  additions: z.number().int().nonnegative(),
  deletions: z.number().int().nonnegative(),
});

export const runVerificationSchema = z.object({
  command: z.literal("node --test"),
  status: z.enum(["PASS", "FAIL", "NOT_RUN"]),
  exitCode: z.number().int().nullable(),
  output: z.string().max(8_000),
});

export const runResultSchema = z.object({
  summary: z.string().max(8_000),
  diffSummary: z.string().max(8_000).nullable(),
  files: z.array(runFileSchema),
  verification: runVerificationSchema.nullable(),
  durationMs: z.number().int().nonnegative(),
  model: z.object({ providerID: z.string(), id: z.string() }).nullable(),
  usage: z.object({
    input: z.number().nonnegative(),
    output: z.number().nonnegative(),
    reasoning: z.number().nonnegative(),
    cacheRead: z.number().nonnegative(),
    cacheWrite: z.number().nonnegative(),
  }).nullable(),
  cost: z.number().nonnegative().nullable(),
  limitation: z.string().max(4_000).nullable(),
});

export const runSchema = z.object({
  id: z.string(),
  actionId: z.string(),
  payloadHash: z.string(),
  status: runStatusSchema,
  createdAt: z.string(),
  updatedAt: z.string(),
  startedAt: z.string().nullable(),
  finishedAt: z.string().nullable(),
  nativeSessionId: z.string().nullable(),
  nativeMessageId: z.string().nullable(),
  cancelRequestedAt: z.string().nullable(),
  lastEventSequence: z.number().int().nonnegative(),
  events: z.array(runEventSchema),
  result: runResultSchema.nullable(),
  failureCode: z.enum([
    "AUTHENTICATION",
    "OPENCODE_UNAVAILABLE",
    "PROVIDER_LIMIT",
    "MISSING_MODEL",
    "PERMISSION_DENIED",
    "VERIFICATION_FAILED",
    "NO_CHANGES",
    "NATIVE_FAILED",
    "MALFORMED_EVENT",
  ]).nullable(),
});

export type MakerRun = z.infer<typeof runSchema>;
export type RunStatus = z.infer<typeof runStatusSchema>;
export type RunEvent = z.infer<typeof runEventSchema>;
export type RunEventCategory = z.infer<typeof runEventCategorySchema>;
export type RunResult = z.infer<typeof runResultSchema>;

export const terminalRunStatuses = new Set<RunStatus>(["SUCCEEDED", "FAILED", "CANCELLED"]);

const allowedTransitions: Record<RunStatus, ReadonlySet<RunStatus>> = {
  QUEUED: new Set(["CONNECTING", "CANCELLED", "FAILED", "UNKNOWN"]),
  CONNECTING: new Set(["RUNNING", "CANCELLED", "FAILED", "UNKNOWN"]),
  RUNNING: new Set(["WAITING_PERMISSION", "VERIFYING", "CANCELLED", "FAILED", "UNKNOWN"]),
  WAITING_PERMISSION: new Set(["RUNNING", "VERIFYING", "CANCELLED", "FAILED", "UNKNOWN"]),
  VERIFYING: new Set(["SUCCEEDED", "CANCELLED", "FAILED", "UNKNOWN"]),
  UNKNOWN: new Set(["RUNNING", "WAITING_PERMISSION", "VERIFYING", "SUCCEEDED", "CANCELLED", "FAILED"]),
  SUCCEEDED: new Set(),
  FAILED: new Set(),
  CANCELLED: new Set(),
};

export class InvalidRunTransition extends Error {}

export function createMakerRun(actionId: string, hash: string, now = new Date()): MakerRun {
  const timestamp = now.toISOString();
  const run = runSchema.parse({
    id: randomUUID(),
    actionId,
    payloadHash: hash,
    status: "QUEUED",
    createdAt: timestamp,
    updatedAt: timestamp,
    startedAt: null,
    finishedAt: null,
    nativeSessionId: null,
    nativeMessageId: null,
    cancelRequestedAt: null,
    lastEventSequence: 0,
    events: [],
    result: null,
    failureCode: null,
  });
  appendRunEvent(run, "state", "Maker run queued.", {}, [], now);
  return run;
}

export function appendRunEvent(
  run: MakerRun,
  category: RunEventCategory,
  summary: string,
  metadata: Record<string, string | number | boolean | null> = {},
  evidenceRefs: string[] = [],
  now = new Date(),
): RunEvent {
  const event = runEventSchema.parse({
    version: 1,
    id: randomUUID(),
    sequence: run.lastEventSequence + 1,
    timestamp: now.toISOString(),
    category,
    summary,
    metadata,
    evidenceRefs,
  });
  run.events.push(event);
  run.lastEventSequence = event.sequence;
  run.updatedAt = event.timestamp;
  return event;
}

export function transitionRun(
  run: MakerRun,
  status: RunStatus,
  event: { category: RunEventCategory; summary: string; metadata?: Record<string, string | number | boolean | null>; evidenceRefs?: string[] },
  now = new Date(),
): RunEvent {
  if (run.status !== status && !allowedTransitions[run.status].has(status)) {
    throw new InvalidRunTransition(`Cannot transition Maker run from ${run.status} to ${status}.`);
  }
  run.status = status;
  if (!run.startedAt && !["QUEUED", "CONNECTING"].includes(status)) run.startedAt = now.toISOString();
  if (terminalRunStatuses.has(status)) run.finishedAt = now.toISOString();
  return appendRunEvent(run, event.category, event.summary, event.metadata, event.evidenceRefs, now);
}

export interface NormalizedNativeEvent {
  category: RunEventCategory;
  summary: string;
  metadata: Record<string, string | number | boolean | null>;
  status?: RunStatus;
  cost?: number;
  usage?: RunResult["usage"];
}

function record(value: unknown): Record<string, unknown> | null {
  return typeof value === "object" && value !== null ? value as Record<string, unknown> : null;
}

function safeString(value: unknown): string | null {
  return typeof value === "string" && value.length <= 200 ? value : null;
}

function sessionData(event: unknown): { type: string; data: Record<string, unknown> } | null {
  const root = record(event);
  const type = safeString(root?.type);
  const data = record(root?.data);
  return type && data ? { type, data } : null;
}

export function nativeEventSessionId(event: unknown): string | null {
  const parsed = sessionData(event);
  if (!parsed) return null;
  const direct = safeString(parsed.data.sessionID);
  if (direct) return direct;
  const form = record(parsed.data.form);
  return safeString(form?.sessionID);
}

export function normalizeNativeEvent(event: unknown): NormalizedNativeEvent | null {
  const parsed = sessionData(event);
  if (!parsed) return null;
  const { type, data } = parsed;

  if (type === "session.execution.started") {
    return { category: "state", summary: "OpenCode started the Maker execution.", metadata: {}, status: "RUNNING" };
  }
  if (type === "session.execution.succeeded") {
    return { category: "state", summary: "OpenCode completed the model execution; evidence collection is next.", metadata: {} };
  }
  if (type === "session.execution.failed") {
    return { category: "state", summary: "OpenCode reported that the model execution failed.", metadata: {} };
  }
  if (type === "session.execution.interrupted") {
    return { category: "state", summary: "OpenCode reported that the session was interrupted.", metadata: {} };
  }
  if (type === "session.step.started") {
    const model = record(data.model);
    const providerID = safeString(model?.providerID);
    const modelID = safeString(model?.id);
    return {
      category: "model",
      summary: "The model started a response step.",
      metadata: {
        ...(providerID ? { providerID } : {}),
        ...(modelID ? { modelID } : {}),
      },
    };
  }
  if (type === "session.step.ended") {
    const tokens = record(data.tokens);
    const cache = record(tokens?.cache);
    const number = (value: unknown) => typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0;
    const cost = number(data.cost);
    return {
      category: "model",
      summary: "The model response step finished.",
      metadata: { finish: safeString(data.finish) ?? "unknown", cost },
      cost,
      usage: {
        input: number(tokens?.input),
        output: number(tokens?.output),
        reasoning: number(tokens?.reasoning),
        cacheRead: number(cache?.read),
        cacheWrite: number(cache?.write),
      },
    };
  }
  if (type === "session.text.started") {
    return { category: "model", summary: "The model started producing a user-visible response.", metadata: {} };
  }
  if (type === "session.text.ended") {
    return { category: "model", summary: "The model finished its user-visible response.", metadata: {} };
  }
  if (type === "session.tool.called") {
    return { category: "tool", summary: "OpenCode started a tool operation.", metadata: { executed: data.executed === true } };
  }
  if (type === "session.tool.success") {
    return { category: "tool", summary: "An OpenCode tool operation completed.", metadata: { executed: data.executed === true } };
  }
  if (type === "session.tool.failed") {
    return { category: "tool", summary: "An OpenCode tool operation failed.", metadata: {} };
  }
  if (type === "permission.asked") {
    return {
      category: "permission",
      summary: "OpenCode is waiting for a permission decision.",
      metadata: { action: safeString(data.action) ?? "unknown", resourceCount: Array.isArray(data.resources) ? data.resources.length : 0 },
      status: "WAITING_PERMISSION",
    };
  }
  if (type === "permission.replied") {
    return { category: "permission", summary: "The OpenCode permission request was answered.", metadata: {}, status: "RUNNING" };
  }
  if (type === "session.retry.scheduled") {
    return {
      category: "model",
      summary: "OpenCode scheduled a provider retry.",
      metadata: { attempt: typeof data.attempt === "number" ? data.attempt : 0 },
    };
  }
  if (type === "session.status") {
    const status = record(data.status);
    const statusType = safeString(status?.type);
    if (statusType === "busy") return { category: "state", summary: "OpenCode reports the session is busy.", metadata: {}, status: "RUNNING" };
    if (statusType === "retry") return { category: "model", summary: "OpenCode is waiting before a provider retry.", metadata: { attempt: typeof status?.attempt === "number" ? status.attempt : 0 } };
    if (statusType === "idle") return { category: "state", summary: "OpenCode reports the session is idle.", metadata: {} };
  }
  return null;
}

export function controlledFailure(error: unknown): { code: MakerRun["failureCode"]; summary: string; uncertain: boolean } {
  const root = record(error);
  const tag = safeString(root?._tag) ?? "";
  const message = error instanceof Error ? error.message : safeString(root?.message) ?? "";
  const lower = `${tag} ${message}`.toLowerCase();
  if (/unauthor|forbidden|authentication|credential/.test(lower)) {
    return { code: "AUTHENTICATION", summary: "OpenCode authentication failed. Match the application and OpenCode server passwords, then retry.", uncertain: false };
  }
  if (/rate.?limit|quota|too many requests|provider limit/.test(lower)) {
    return { code: "PROVIDER_LIMIT", summary: "The configured provider reported a quota or rate limit.", uncertain: false };
  }
  if (/model.+not found|missing model|model.+unavailable/.test(lower)) {
    return { code: "MISSING_MODEL", summary: "The required OpenCode model is unavailable.", uncertain: false };
  }
  if (/permission|denied|rejected/.test(lower)) {
    return { code: "PERMISSION_DENIED", summary: "OpenCode denied a required Maker permission.", uncertain: false };
  }
  if (/timeout|timed out|econn|fetch|network|socket|unavailable|abort/.test(lower)) {
    return { code: "OPENCODE_UNAVAILABLE", summary: "The OpenCode outcome is unknown because the connection ended before confirmation.", uncertain: true };
  }
  return { code: "NATIVE_FAILED", summary: "OpenCode could not complete the Maker run.", uncertain: false };
}

