      mutation(run, current);
      events = run.events.filter((event) => event.sequence > before);
      return current;
    });
    const run = requiredRun(project, runId);
    for (const event of events) this.broker.publish(run, event);
    return project;
  }
}

function requiredRun(project: Project, runId: string): MakerRun {
  const run = project.runs.find((item) => item.id === runId);
  if (!run) throw new Error(`Unknown Maker run: ${runId}`);
  return run;
}

function emptyResult(run: MakerRun, limitation: string): RunResult {
