:root {
  color: #f4f0e8;
  background: #111018;
  font-family: ui-sans-serif, system-ui, sans-serif;
  --bg: #111018;
  --surface: #1b1824;
  --raised: #252031;
  --text: #f4f0e8;
  --muted: #b8afca;
  --accent: #f4b66c;
  --spirit: #bfa3ff;
  --success: #8bd5a7;
  --danger: #ffb4a8;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 20% 0%, rgb(244 182 108 / 16%), transparent 28rem),
    var(--bg);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-style: solid;
  outline-offset: 3px;
  box-shadow: 0 0 0 3px var(--accent);
}

.skip {
  position: absolute;
  left: var(--space-4);
  top: -4rem;
  background: var(--accent);
