import type { MakerRun, RunEvent } from "./model.ts";

export type RunStreamItem =
  | { type: "snapshot"; run: MakerRun; events: RunEvent[]; resync: boolean }
  | { type: "event"; run: MakerRun; event: RunEvent }
  | { type: "heartbeat"; cursor: number };

interface Subscriber {
  after: number;
  push: (run: MakerRun, event: RunEvent) => void;
}

export class RunEventBroker {
  private readonly subscribers = new Map<string, Set<Subscriber>>();

  publish(run: MakerRun, event: RunEvent): void {
    for (const subscriber of this.subscribers.get(run.id) ?? []) {
      if (event.sequence > subscriber.after) {
        subscriber.after = event.sequence;
        subscriber.push(run, event);
      }
    }
  }

  async *stream(
    initial: MakerRun,
    requestedCursor: number | null,
    signal: AbortSignal,
    heartbeatMs = 15_000,
  ): AsyncGenerator<RunStreamItem> {
    const cursorValid = requestedCursor !== null
      && Number.isInteger(requestedCursor)
      && requestedCursor >= 0
      && requestedCursor <= initial.lastEventSequence;
    let cursor = cursorValid ? requestedCursor : 0;
    const pending = initial.events.filter((event) => event.sequence > cursor);
    if (!cursorValid && requestedCursor !== null) {
      yield { type: "snapshot", run: structuredClone(initial), events: structuredClone(initial.events), resync: true };
      cursor = initial.lastEventSequence;
    } else {
      for (const event of pending) {
        cursor = event.sequence;
        yield { type: "event", run: structuredClone(initial), event: structuredClone(event) };
      }
    }
    if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(initial.status)) return;

    const queue: Array<{ run: MakerRun; event: RunEvent }> = [];
    let wake: (() => void) | null = null;
    const subscriber: Subscriber = {
      after: cursor,
      push: (run, event) => {
        queue.push({ run: structuredClone(run), event: structuredClone(event) });
        wake?.();
      },
    };
    const set = this.subscribers.get(initial.id) ?? new Set<Subscriber>();
    set.add(subscriber);
    this.subscribers.set(initial.id, set);

    try {
      while (!signal.aborted) {
        if (!queue.length) {
          await new Promise<void>((resolve) => {
            wake = resolve;
            const timer = setTimeout(resolve, heartbeatMs);
            signal.addEventListener("abort", resolve, { once: true });
            const original = wake;
            wake = () => {
              clearTimeout(timer);
              original?.();
            };
          });
          wake = null;
        }
        if (signal.aborted) return;
        const item = queue.shift();
        if (!item) {
          yield { type: "heartbeat", cursor: subscriber.after };
          continue;
        }
        yield { type: "event", run: item.run, event: item.event };
        if (["SUCCEEDED", "FAILED", "CANCELLED"].includes(item.run.status)) return;
      }
    } finally {
      set.delete(subscriber);
      if (!set.size) this.subscribers.delete(initial.id);
    }
  }
}
