import { z } from "zod";

export const runStatusSchema = z.enum([
  "QUEUED",
  "CONNECTING",
  "RUNNING",
  "WAITING_PERMISSION",
  "VERIFYING",
  "SUCCEEDED",
  "FAILED",
  "CANCELLED",
  "UNKNOWN",
]);

export const runEventCategorySchema = z.enum([
  "state",
  "session",
  "model",
  "tool",
  "permission",
  "files",
  "verification",
  "result",
  "recovery",
]);

const eventMetadataValueSchema = z.union([z.string(), z.number(), z.boolean(), z.null()]);

export const runEventSchema = z.object({
  version: z.literal(1),
  id: z.string(),
  sequence: z.number().int().positive(),
  timestamp: z.string(),
  category: runEventCategorySchema,
  summary: z.string().min(1).max(1_000),
  metadata: z.record(z.string(), eventMetadataValueSchema),
  evidenceRefs: z.array(z.string()),
});

export const runFileSchema = z.object({
  path: z.string(),
  status: z.enum(["added", "deleted", "modified"]),
  additions: z.number().int().nonnegative(),
  deletions: z.number().int().nonnegative(),
});

export const runVerificationSchema = z.object({
  command: z.literal("node --test"),
  status: z.enum(["PASS", "FAIL", "NOT_RUN"]),
  exitCode: z.number().int().nullable(),
  output: z.string().max(8_000),
});

export const runResultSchema = z.object({
  summary: z.string().max(8_000),
  diffSummary: z.string().max(8_000).nullable(),
  files: z.array(runFileSchema),
  verification: runVerificationSchema.nullable(),
  durationMs: z.number().int().nonnegative(),
  model: z.object({ providerID: z.string(), id: z.string() }).nullable(),
  usage: z.object({
    input: z.number().nonnegative(),
    output: z.number().nonnegative(),
    reasoning: z.number().nonnegative(),
    cacheRead: z.number().nonnegative(),
    cacheWrite: z.number().nonnegative(),
  }).nullable(),
  cost: z.number().nonnegative().nullable(),
  limitation: z.string().max(4_000).nullable(),
});

export const runSchema = z.object({
  id: z.string(),
  actionId: z.string(),
  payloadHash: z.string(),
  status: runStatusSchema,
  createdAt: z.string(),
  updatedAt: z.string(),
  startedAt: z.string().nullable(),
  finishedAt: z.string().nullable(),
  nativeSessionId: z.string().nullable(),
  nativeMessageId: z.string().nullable(),
  cancelRequestedAt: z.string().nullable(),
  lastEventSequence: z.number().int().nonnegative(),
  events: z.array(runEventSchema),
  result: runResultSchema.nullable(),
  failureCode: z.enum([
    "AUTHENTICATION",
    "OPENCODE_UNAVAILABLE",
    "PROVIDER_LIMIT",
    "MISSING_MODEL",
    "PERMISSION_DENIED",
    "VERIFICATION_FAILED",
    "NO_CHANGES",
    "NATIVE_FAILED",
    "MALFORMED_EVENT",
  ]).nullable(),
});

export type MakerRun = z.infer<typeof runSchema>;
export type RunStatus = z.infer<typeof runStatusSchema>;
export type RunEvent = z.infer<typeof runEventSchema>;
export type RunEventCategory = z.infer<typeof runEventCategorySchema>;
export type RunResult = z.infer<typeof runResultSchema>;

export const terminalRunStatuses = new Set<RunStatus>(["SUCCEEDED", "FAILED", "CANCELLED"]);

const allowedTransitions: Record<RunStatus, ReadonlySet<RunStatus>> = {
  QUEUED: new Set(["CONNECTING", "CANCELLED", "FAILED", "UNKNOWN"]),
  CONNECTING: new Set(["RUNNING", "CANCELLED", "FAILED", "UNKNOWN"]),
  RUNNING: new Set(["WAITING_PERMISSION", "VERIFYING", "CANCELLED", "FAILED", "UNKNOWN"]),
  WAITING_PERMISSION: new Set(["RUNNING", "VERIFYING", "CANCELLED", "FAILED", "UNKNOWN"]),
  VERIFYING: new Set(["SUCCEEDED", "CANCELLED", "FAILED", "UNKNOWN"]),
  UNKNOWN: new Set(["RUNNING", "WAITING_PERMISSION", "VERIFYING", "SUCCEEDED", "CANCELLED", "FAILED"]),
  SUCCEEDED: new Set(),
  FAILED: new Set(),
  CANCELLED: new Set(),
};

export class InvalidRunTransition extends Error {}

export function createMakerRun(actionId: string, hash: string, now = new Date()): MakerRun {
  const timestamp = now.toISOString();
  const run = runSchema.parse({
    id: randomUUID(),
    actionId,
    payloadHash: hash,
    status: "QUEUED",
    createdAt: timestamp,
    updatedAt: timestamp,
    startedAt: null,
    finishedAt: null,
    nativeSessionId: null,
    nativeMessageId: null,
    cancelRequestedAt: null,
    lastEventSequence: 0,
    events: [],
    result: null,
    failureCode: null,
  });
  appendRunEvent(run, "state", "Maker run queued.", {}, [], now);
  return run;
}

export function appendRunEvent(
  run: MakerRun,
  category: RunEventCategory,
  summary: string,
  metadata: Record<string, string | number | boolean | null> = {},
  evidenceRefs: string[] = [],
  now = new Date(),
): RunEvent {
  const event = runEventSchema.parse({
    version: 1,
    id: randomUUID(),
    sequence: run.lastEventSequence + 1,
    timestamp: now.toISOString(),
    category,
    summary,
    metadata,
    evidenceRefs,
  });
  run.events.push(event);
  run.lastEventSequence = event.sequence;
  run.updatedAt = event.timestamp;
  return event;
}

export function transitionRun(
  run: MakerRun,
  status: RunStatus,
  event: { category: RunEventCategory; summary: string; metadata?: Record<string, string | number | boolean | null>; evidenceRefs?: string[] },
  now = new Date(),
): RunEvent {
  if (run.status !== status && !allowedTransitions[run.status].has(status)) {
    throw new InvalidRunTransition(`Cannot transition Maker run from ${run.status} to ${status}.`);
  }
  run.status = status;
  if (!run.startedAt && !["QUEUED", "CONNECTING"].includes(status)) run.startedAt = now.toISOString();
  if (terminalRunStatuses.has(status)) run.finishedAt = now.toISOString();
  return appendRunEvent(run, event.category, event.summary, event.metadata, event.evidenceRefs, now);
}

