function record(value: unknown): Record<string, unknown> | null {
  return typeof value === "object" && value !== null ? value as Record<string, unknown> : null;
}

function safeString(value: unknown): string | null {
  return typeof value === "string" && value.length <= 200 ? value : null;
}

function sessionData(event: unknown): { type: string; data: Record<string, unknown> } | null {
  const root = record(event);
  const type = safeString(root?.type);
  const data = record(root?.data);
  return type && data ? { type, data } : null;
}

export function nativeEventSessionId(event: unknown): string | null {
  const parsed = sessionData(event);
  if (!parsed) return null;
  const direct = safeString(parsed.data.sessionID);
  if (direct) return direct;
  const form = record(parsed.data.form);
  return safeString(form?.sessionID);
}

