} from "./model.ts";

class MakerTimeout extends Error {}

export interface RunCoordinatorOptions {
  demoWorkspace: string;
  promptRoot?: string;
  timeoutMs?: number;
  maxConcurrent?: number;
}

export class RunCoordinator {
  private readonly active = new Map<string, Promise<void>>();
  private readonly pending: Array<{ runId: string; recovery: boolean }> = [];
  private readonly maxConcurrent: number;

  constructor(
    private readonly workflow: WorkflowService,
    private readonly guide: SpiritGuide,
    readonly broker: RunEventBroker,
    private readonly options: RunCoordinatorOptions,
  ) {
    this.maxConcurrent = Math.max(1, options.maxConcurrent ?? 1);
  }

  announce(run: MakerRun): void {
    const event = run.events.at(-1);
    if (event) this.broker.publish(run, event);
  }

  schedule(runId: string): void {
    this.enqueue(runId, false);
  }

  scheduleRecovery(runId: string): void {
    this.enqueue(runId, true);
  }

  async recoverOnStartup(): Promise<void> {
    const project = await this.workflow.get();
    for (const run of project.runs) {
      if (!terminalRunStatuses.has(run.status)) this.scheduleRecovery(run.id);
    }
  }

  async waitForIdle(runId: string): Promise<void> {
    for (;;) {
      const active = this.active.get(runId);
      if (active) await active;
      if (!this.active.has(runId) && !this.pending.some((item) => item.runId === runId)) return;
      await new Promise((resolve) => setTimeout(resolve, 0));
    }
  }

  async cancel(runId: string): Promise<Project> {
    let project = await this.updateRun(runId, (run) => {
      if (terminalRunStatuses.has(run.status)) throw new InvalidRunTransition("A finished Maker run cannot be cancelled.");
      if (!run.cancelRequestedAt) {
        run.cancelRequestedAt = new Date().toISOString();
        appendRunEvent(run, "state", "Cancellation requested; waiting for OpenCode confirmation.");
      }
    });
    let run = requiredRun(project, runId);
    if (!run.nativeSessionId) {
      if (run.status === "QUEUED" || run.status === "CONNECTING") {
        project = await this.updateRun(runId, (current) => {
          transitionRun(current, "CANCELLED", { category: "result", summary: "Maker run cancelled before an OpenCode session started." });
          current.result = emptyResult(current, "No OpenCode session or workspace change was created.");
        });
        return project;
      }
      return this.markUnknown(runId, "Cancellation could not be confirmed because no OpenCode session reference is available.");
    }

    const interrupted = await this.guide.interruptMaker(run.nativeSessionId, { conversationId: project.id });
    if (!interrupted) return this.markUnknown(runId, "OpenCode did not confirm interruption; reconcile the saved session before retrying.");
    const snapshot = await this.guide.inspectMaker(run.nativeSessionId, { conversationId: project.id });
    if (snapshot.outcome === "interrupted") return this.markCancelled(runId, snapshot, "OpenCode confirmed the Maker session was interrupted.");
    if (snapshot.outcome === "succeeded" || snapshot.outcome === "failed") {
      this.scheduleRecovery(runId);
    } else {
      project = await this.updateRun(runId, (current) => {
        appendRunEvent(current, "state", "OpenCode accepted the interrupt; terminal confirmation is pending.");
      });
    }
    return project;
  }

  async reconcile(runId: string): Promise<Project> {
    const project = await this.workflow.get();
    const run = requiredRun(project, runId);
    if (terminalRunStatuses.has(run.status)) return project;
    if (!run.nativeSessionId) return this.markUnknown(runId, "No native session exists to reconcile. Start a new run only after reviewing this outcome.");
    const snapshot = await this.guide.inspectMaker(run.nativeSessionId, { conversationId: project.id });
    if (snapshot.outcome === "interrupted") return this.markCancelled(runId, snapshot, "Reconciliation found an interrupted OpenCode session.");
    if (snapshot.outcome === "succeeded" || snapshot.outcome === "failed") {
      this.scheduleRecovery(runId);
      return this.updateRun(runId, (current) => appendRunEvent(current, "recovery", "Native terminal state found; evidence reconciliation is running."));
    }
    if (snapshot.running) {
      const updated = await this.updateRun(runId, (current) => {
        if (current.status === "UNKNOWN") transitionRun(current, "RUNNING", { category: "recovery", summary: "Reattached to the running OpenCode session." });
        else appendRunEvent(current, "recovery", "The saved OpenCode session is still running.");
      });
      this.scheduleRecovery(runId);
      return updated;
    }
    return this.markUnknown(runId, "The saved OpenCode session is idle without a terminal outcome.");
  }

  private enqueue(runId: string, recovery: boolean): void {
    if (this.active.has(runId) || this.pending.some((item) => item.runId === runId)) return;
    this.pending.push({ runId, recovery });
    queueMicrotask(() => this.drain());
  }

  private drain(): void {
    while (this.active.size < this.maxConcurrent && this.pending.length) {
      const item = this.pending.shift()!;
      const task = (item.recovery ? this.recover(item.runId) : this.execute(item.runId))
        .catch(async (error) => {
          await this.recordCoordinatorFailure(item.runId, error).catch(() => undefined);
        })
        .finally(() => {
          this.active.delete(item.runId);
          this.drain();
        });
      this.active.set(item.runId, task);
    }
  }

  private async execute(runId: string): Promise<void> {
    let project = await this.updateRun(runId, (run) => {
      transitionRun(run, "CONNECTING", { category: "state", summary: "Connecting to OpenCode and creating a Maker session." });
    });
    let run = requiredRun(project, runId);
    if (run.cancelRequestedAt) return;

    const created = await this.guide.createMakerSession({ conversationId: project.id, workspace: this.options.demoWorkspace });
    const messageId = `msg_${randomUUID()}`;
    project = await this.updateRun(runId, (current, nextProject) => {
      current.nativeSessionId = created.sessionId;
      current.nativeMessageId = messageId;
      current.startedAt = current.startedAt ?? new Date().toISOString();
      rememberSession(nextProject, "maker", created.sessionId);
      appendRunEvent(current, "session", "OpenCode Maker session created and saved before execution.", {
        sessionId: created.sessionId,
        messageId,
        providerID: created.model?.providerID ?? "unknown",
        modelID: created.model?.id ?? "unknown",
      });
    });
    run = requiredRun(project, runId);
    if (run.cancelRequestedAt) {
      await this.cancel(runId);
      return;
    }

    const eventAbort = new AbortController();
    const pump = this.pumpEvents(runId, created.sessionId, eventAbort.signal);
    try {
      const makerScope = project.makerScope.statement;
      if (!makerScope) throw new Error("Maker scope disappeared before execution.");
      const prompt = await buildSpiritInstructions("maker", project, makerScope, this.options.promptRoot);
      await this.updateRun(runId, (current) => {
        transitionRun(current, "RUNNING", { category: "state", summary: "Maker prompt accepted for delivery to the saved OpenCode session." });
      });
      await this.guide.promptMaker({ sessionId: created.sessionId, messageId, prompt });
      await this.waitBounded(created.sessionId);
      await this.finalizeFromNative(runId);
    } catch (error) {
      if (error instanceof MakerTimeout) {
        await this.markUnknown(runId, "The local wait timed out. The saved OpenCode session was not interrupted or retried; reconcile it before another run.");
      } else {
        await this.recordCoordinatorFailure(runId, error);
      }
    } finally {
      eventAbort.abort();
      await pump.catch(() => undefined);
    }
  }

  private async recover(runId: string): Promise<void> {
    const project = await this.workflow.get();
    const run = requiredRun(project, runId);
    if (terminalRunStatuses.has(run.status)) return;
    if (!run.nativeSessionId) {
      await this.markUnknown(runId, "The process restarted before an OpenCode session reference was saved; the run was not retried.");
      return;
    }
    const snapshot = await this.guide.inspectMaker(run.nativeSessionId, { conversationId: project.id });
    if (snapshot.running) {
      await this.updateRun(runId, (current) => {
        if (current.status === "UNKNOWN") transitionRun(current, "RUNNING", { category: "recovery", summary: "Restart recovery reattached to the running OpenCode session." });
        else appendRunEvent(current, "recovery", "Restart recovery found the OpenCode session still running.");
      });
      const eventAbort = new AbortController();
      const pump = this.pumpEvents(runId, run.nativeSessionId, eventAbort.signal);
      try {
        await this.waitBounded(run.nativeSessionId);
        await this.finalizeFromNative(runId);
      } catch (error) {
        if (error instanceof MakerTimeout) await this.markUnknown(runId, "Restart recovery timed out while the saved OpenCode session remained non-terminal.");
        else await this.recordCoordinatorFailure(runId, error);
      } finally {
        eventAbort.abort();
        await pump.catch(() => undefined);
      }
      return;
    }
    await this.finalizeSnapshot(runId, snapshot);
  }

  private async waitBounded(sessionId: string): Promise<void> {
    const abort = new AbortController();
    const timeout = setTimeout(() => abort.abort(), this.options.timeoutMs ?? 180_000);
    try {
      await this.guide.waitMaker(sessionId, abort.signal);
    } catch (error) {
      if (abort.signal.aborted) throw new MakerTimeout("Maker wait timed out.");
      throw error;
    } finally {
      clearTimeout(timeout);
    }
  }

  private async pumpEvents(runId: string, sessionId: string, signal: AbortSignal): Promise<void> {
    try {
      for await (const nativeEvent of this.guide.makerEvents(signal)) {
        if (signal.aborted) return;
        if (nativeEventSessionId(nativeEvent) !== sessionId) continue;
        const normalized = normalizeNativeEvent(nativeEvent);
        if (!normalized) continue;
        await this.updateRun(runId, (run) => {
          if (terminalRunStatuses.has(run.status)) return;
          if (normalized.status && normalized.status !== run.status) {
            try {
              transitionRun(run, normalized.status, normalized);
              return;
            } catch (error) {
              if (!(error instanceof InvalidRunTransition)) throw error;
            }
          }
          appendRunEvent(run, normalized.category, normalized.summary, normalized.metadata);
        });
      }
    } catch (error) {
      if (!signal.aborted) {
        await this.updateRun(runId, (run) => {
          if (!terminalRunStatuses.has(run.status)) appendRunEvent(run, "recovery", "OpenCode event streaming disconnected; terminal state will be reconciled directly.");
        });
      }
    }
  }

  private async finalizeFromNative(runId: string): Promise<Project> {
    const project = await this.workflow.get();
    const run = requiredRun(project, runId);
    if (!run.nativeSessionId) return this.markUnknown(runId, "The native session reference is missing during finalization.");
    const snapshot = await this.guide.inspectMaker(run.nativeSessionId, { conversationId: project.id });
    return this.finalizeSnapshot(runId, snapshot);
  }

  private async finalizeSnapshot(runId: string, snapshot: MakerSessionSnapshot): Promise<Project> {
    if (snapshot.running || !snapshot.outcome) return this.markUnknown(runId, "OpenCode has not exposed a terminal outcome; the saved session remains reconcilable.");
    if (snapshot.outcome === "interrupted") return this.markCancelled(runId, snapshot, "OpenCode confirmed that the Maker session was interrupted.");
    if (snapshot.outcome === "failed") {
      return this.finishFailure(runId, snapshot, "NATIVE_FAILED", "OpenCode reported that the Maker session failed.", null, null);
    }

    let project = await this.updateRun(runId, (run) => {
      if (run.status !== "VERIFYING") transitionRun(run, "VERIFYING", { category: "verification", summary: "Collecting file changes and running the approved Node verification." });
    });
    const run = requiredRun(project, runId);
    if (!run.nativeSessionId) return this.markUnknown(runId, "The native session reference disappeared before evidence collection.");
    const diff = await this.guide.diffMaker(run.nativeSessionId, { conversationId: project.id });
    if (!diff.length) return this.finishFailure(runId, snapshot, "NO_CHANGES", "OpenCode finished without a file change.", diff, null);
    const check = await runApprovedNodeCheck(this.options.demoWorkspace);
    if (check.code !== 0) {
      return this.finishFailure(runId, snapshot, "VERIFICATION_FAILED", "Maker changed files, but the approved Node verification failed.", diff, check);
    }

    project = await this.updateRun(runId, (current, nextProject) => {
      const evidenceIds = recordEvidence(nextProject, current, diff, check);
      current.result = resultFrom(snapshot, current, "Maker completed with file changes and a passing Node verification.", diff, check, null);
      transitionRun(current, "SUCCEEDED", {
        category: "result",
        summary: "Maker completed with verified evidence.",
        metadata: { fileCount: diff.length, verification: "PASS" },
        evidenceRefs: evidenceIds,
      });
      rememberTranscript(nextProject, "maker", current.result.diffSummary ?? current.result.summary);
      refreshNextAction(nextProject);
    });
    return project;
  }

  private async finishFailure(
    runId: string,
    snapshot: MakerSessionSnapshot,
    code: NonNullable<MakerRun["failureCode"]>,
    summary: string,
    diff: FileDiffInfo[] | null,
    check: { code: number | null; output: string } | null,
  ): Promise<Project> {
    return this.updateRun(runId, (run, project) => {
      const evidenceIds = recordEvidence(project, run, diff ?? [], check);
      run.failureCode = code;
      run.result = resultFrom(snapshot, run, summary, diff ?? [], check, summary);
      transitionRun(run, "FAILED", {
        category: "result",
        summary,
        metadata: { fileCount: diff?.length ?? 0, verification: check ? (check.code === 0 ? "PASS" : "FAIL") : "NOT_RUN" },
        evidenceRefs: evidenceIds,
      });
      rememberTranscript(project, "system", summary);
      refreshNextAction(project);
    });
  }

  private async markCancelled(runId: string, snapshot: MakerSessionSnapshot, summary: string): Promise<Project> {
    return this.updateRun(runId, (run, project) => {
      if (!terminalRunStatuses.has(run.status)) transitionRun(run, "CANCELLED", { category: "result", summary });
      run.result = resultFrom(snapshot, run, summary, [], null, "Diff and verification were not collected for an interrupted run.");
      rememberTranscript(project, "system", summary);
      refreshNextAction(project);
    });
  }

  private async markUnknown(runId: string, summary: string): Promise<Project> {
    return this.updateRun(runId, (run, project) => {
      if (!terminalRunStatuses.has(run.status) && run.status !== "UNKNOWN") transitionRun(run, "UNKNOWN", { category: "recovery", summary });
      else if (run.status === "UNKNOWN") appendRunEvent(run, "recovery", summary);
      rememberTranscript(project, "system", summary);
      refreshNextAction(project);
    });
  }

  private async recordCoordinatorFailure(runId: string, error: unknown): Promise<Project> {
