export const runStatusSchema = z.enum([
  "QUEUED",
  "CONNECTING",
  "RUNNING",
  "WAITING_PERMISSION",
  "VERIFYING",
  "SUCCEEDED",
  "FAILED",
  "CANCELLED",
  "UNKNOWN",
]);

export const runEventCategorySchema = z.enum([
  "state",
  "session",
  "model",
  "tool",
  "permission",
  "files",
  "verification",
  "result",
  "recovery",
]);

