export function controlledFailure(error: unknown): { code: MakerRun["failureCode"]; summary: string; uncertain: boolean } {
  const root = record(error);
  const tag = safeString(root?._tag) ?? "";
  const message = error instanceof Error ? error.message : safeString(root?.message) ?? "";
  const lower = `${tag} ${message}`.toLowerCase();
  if (/unauthor|forbidden|authentication|credential/.test(lower)) {
    return { code: "AUTHENTICATION", summary: "OpenCode authentication failed. Match the application and OpenCode server passwords, then retry.", uncertain: false };
  }
  if (/rate.?limit|quota|too many requests|provider limit/.test(lower)) {
    return { code: "PROVIDER_LIMIT", summary: "The configured provider reported a quota or rate limit.", uncertain: false };
  }
  if (/model.+not found|missing model|model.+unavailable/.test(lower)) {
    return { code: "MISSING_MODEL", summary: "The required OpenCode model is unavailable.", uncertain: false };
  }
  if (/permission|denied|rejected/.test(lower)) {
    return { code: "PERMISSION_DENIED", summary: "OpenCode denied a required Maker permission.", uncertain: false };
  }
  if (/timeout|timed out|econn|fetch|network|socket|unavailable|abort/.test(lower)) {
    return { code: "OPENCODE_UNAVAILABLE", summary: "The OpenCode outcome is unknown because the connection ended before confirmation.", uncertain: true };
  }
  return { code: "NATIVE_FAILED", summary: "OpenCode could not complete the Maker run.", uncertain: false };
}
