import { buildSpiritInstructions } from "./instructions.ts";
import {
  extractJsonObject,
  formatSectionDraft,
  oracleReplySchema,
  sectionReplySchema,
  witnessReplySchema,
} from "./parse.ts";
import { traceAgentOperation } from "./telemetry.ts";

export class ExperienceFailure extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: number,
    readonly retryable: boolean,
    readonly operationId: string | null = null,
  ) {
    super(message);
  }
}

interface Claimed {
  project: Project;
  duplicate: boolean;
}

export class ExperienceService {
  constructor(
    private readonly workflow: WorkflowService,
    private readonly store: AtomicProjectStore,
    private readonly guide: SpiritGuide,
    private readonly coordinator: RunCoordinator,
    private readonly options: { safeDirectory: string; demoWorkspace: string; promptRoot?: string },
  ) {}

  async sendMessage(actionId: string, expectedRevision: number, intent: "clarify" | "draft" | "question" | "witness", text: string) {
    const payload = { intent, text };
    const claimed = await this.claim(actionId, payload, expectedRevision);
    if (claimed.duplicate) return { project: claimed.project, duplicate: true };
    const project = claimed.project;
    try {
      if (intent === "clarify") return await this.clarify(actionId, payload, expectedRevision, project, text);
      if (intent === "draft") return await this.draft(actionId, payload, expectedRevision, project, text);
      if (intent === "question") return await this.question(actionId, payload, expectedRevision, project, text);
      return await this.witness(actionId, payload, expectedRevision, project, text);
    } catch (error) {
      if (error instanceof ExperienceFailure || error instanceof WorkflowConflict || error instanceof RevisionConflict) throw error;
      return this.recordUncertain(actionId, payload, expectedRevision, intent, error);
    }
  }

  async approve(actionId: string, expectedRevision: number, kind: "product" | "maker-scope", statement?: string) {
    const payload = { kind, statement: statement ?? null };
    return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
      if (kind === "product") return approveProduct(project);
      return grantMakerScope(project, statement ?? "");
    });
  }

  async queueMaker(actionId: string, expectedRevision: number) {
    const payload = { intent: "maker" };
    const result = await this.workflow.execute(actionId, payload, expectedRevision, (current) => {
      if (current.makerScope.status !== "GRANTED" || !current.makerScope.statement) {
        throw new ExperienceFailure("Grant a separate Maker scope before a native run.", "MAKER_SCOPE_REQUIRED", 409, false);
      }
      const active = current.runs.find((run) => !terminalRunStatuses.has(run.status));
      if (active) throw new ExperienceFailure(`Maker run ${active.id} is already active.`, "RUN_ALREADY_ACTIVE", 409, false, active.id);
      current.runs.push(createMakerRun(actionId, payloadHash(payload)));
      return refreshNextAction(current);
    });
    const run = result.project.runs.find((item) => item.actionId === actionId);
    if (!run) throw new ExperienceFailure("The saved Maker run could not be found.", "RUN_NOT_FOUND", 500, false);
    if (!result.duplicate) {
      this.coordinator.announce(run);
      this.coordinator.schedule(run.id);
    }
    return { project: result.project, run, duplicate: result.duplicate };
  }

  async cancel(actionId: string, expectedRevision: number, runId: string) {
    const claimed = await this.workflow.execute(actionId, { runId, intent: "cancel" }, expectedRevision, (project) => project);
    if (claimed.duplicate) return { project: claimed.project, run: claimed.project.runs.find((run) => run.id === runId), duplicate: true };
    const project = await this.coordinator.cancel(runId);
    return { project, run: project.runs.find((run) => run.id === runId), duplicate: false };
  }

  async reconcile(actionId: string, expectedRevision: number, runId: string) {
    const claimed = await this.workflow.execute(actionId, { runId, intent: "reconcile" }, expectedRevision, (project) => project);
    if (claimed.duplicate) return { project: claimed.project, run: claimed.project.runs.find((run) => run.id === runId), duplicate: true };
    const project = await this.coordinator.reconcile(runId);
    return { project, run: project.runs.find((run) => run.id === runId), duplicate: false };
  }

  async getRun(runId: string) {
    const project = await this.workflow.get();
    const run = project.runs.find((item) => item.id === runId);
    if (!run) throw new ExperienceFailure("That Maker run does not exist.", "RUN_NOT_FOUND", 404, false);
    return { project, run };
  }

  async *runEvents(runId: string, cursor: number | null, signal: AbortSignal) {
    const { run } = await this.getRun(runId);
    yield* this.coordinator.broker.stream(run, cursor, signal);
  }

  async exportApproved() {
    const project = await this.workflow.get();
    const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
    const plan = unresolved.length
      ? null
      : project.sections
        .toSorted((left, right) => left.order - right.order)
        .map((section) => `## ${section.title}\n\n${section.content}`)
        .join("\n\n");
    return {
      plan,
      unresolved: unresolved.map((section) => section.id),
      drafts: project.witnessDrafts.map((draft) => ({ title: draft.title, content: draft.content })),
      limitation: "Witness drafts are in-app review notes. They are not a submitted article, video, or entry.",
    };
  }

  private async clarify(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
    return traceAgentOperation("oracle", project.id, async () => {
      if (project.product.status === "APPROVED") {
        throw new ExperienceFailure("The product proposal is already approved.", "PRODUCT_ALREADY_APPROVED", 409, false);
      }
      const spoken = await this.guide.speak({
        role: "oracle",
        conversationId: project.id,
        sessionId: sessionFor(project, "oracle"),
        prompt: await this.instructions("oracle", project, text),
        workspace: this.options.safeDirectory,
      });
      const reply = oracleReplySchema.parse(extractJsonObject(spoken.text));
      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
        const seeded = structuredClone(current);
        rememberTranscript(seeded, "user", text);
        const next = recordOracleProposal(seeded, { ...reply, sessionId: spoken.sessionId });
        next.operations.push(operation("guide", payload, spoken, "Oracle proposal stored. It is not approved."));
        return refreshNextAction(next);
      });
    });
  }

  private async draft(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
    return traceAgentOperation("architect", project.id, async () => {
      if (project.product.status !== "APPROVED" || !project.currentSectionId) {
        throw new ExperienceFailure("Drafting waits for an approved product and an active section.", "SECTION_NOT_READY", 409, false);
      }
      const sectionId = project.currentSectionId;
      const spoken = await this.guide.speak({
        role: "architect",
        conversationId: project.id,
        sessionId: sessionFor(project, "architect"),
        prompt: await this.instructions("architect", project, text),
        workspace: this.options.safeDirectory,
      });
      let reply;
      try {
        reply = sectionReplySchema.parse(extractJsonObject(spoken.text));
      } catch {
        const prose = spoken.text.trim();
        if (prose.length < 80) {
          return this.recordFailure(actionId, payload, expectedRevision, "architect", spoken.sessionId, `The Architect reply was malformed, so the section was left unchanged. Reply began: ${prose.slice(0, 240)}`);
        }
        reply = {
          content: prose.slice(0, 12_000),
          recommendation: "The Architect returned prose. Review the draft before approval.",
          tradeoff: "Separate recommendation and tradeoff fields were not returned.",
        };
      }
      const content = formatSectionDraft(reply);
      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
        const next = reviseSection(current, sectionId, content);
        rememberSession(next, "architect", spoken.sessionId);
        rememberTranscript(next, "user", text);
        rememberTranscript(next, "architect", content);
        next.operations.push(operation("guide", payload, spoken, "Draft stored as the current section version."));
        return refreshNextAction(next);
      });
    });
  }

  private async question(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
    const role = project.stage === "ORACLE" ? "oracle" : "architect";
    return traceAgentOperation(role, project.id, async () => {
      const spoken = await this.guide.speak({
        role,
        conversationId: project.id,
        sessionId: sessionFor(project, role),
        prompt: await this.instructions(role, project, `The user is asking a question. This is not approval and must not change an approved artifact.\n\n${text}`),
        workspace: this.options.safeDirectory,
      });
      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
        const next = structuredClone(current);
        rememberSession(next, role, spoken.sessionId);
        rememberTranscript(next, "user", text);
        rememberTranscript(next, role, spoken.text.slice(0, 4_000));
        next.operations.push(operation("guide", payload, spoken, "Question answered without changing approvals."));
        return refreshNextAction(next);
      });
    });
  }

  private async witness(actionId: string, payload: object, expectedRevision: number, project: Project, text: string) {
    return traceAgentOperation("witness", project.id, async () => {
      const makerDone = project.runs.some((run) => run.status === "SUCCEEDED")
        || project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED");
      if (!makerDone) throw new ExperienceFailure("Witness review waits for a completed Maker run.", "WITNESS_NOT_READY", 409, false);
      const spoken = await this.guide.speak({
        role: "witness",
        conversationId: project.id,
        sessionId: null,
        prompt: await this.instructions("witness", project, text),
        workspace: this.options.safeDirectory,
      });
      let reply;
      try {
        reply = witnessReplySchema.parse(extractJsonObject(spoken.text));
      } catch {
        const prose = spoken.text.trim();
        if (prose.length < 80) {
          return this.recordFailure(actionId, payload, expectedRevision, "witness", spoken.sessionId, `The Witness reply was malformed, so no draft was stored. Reply began: ${prose.slice(0, 240)}`);
        }
        reply = {
          findings: prose.slice(0, 8_000),
          limitations: "The Witness returned prose rather than separate fields.",
          draftNotes: "These notes are an in-app review. They are not a submitted article or video.",
        };
      }
      return this.workflow.execute(actionId, payload, expectedRevision, (current) => {
        const next = recordWitnessDrafts(current, [
          { title: "Findings", content: reply.findings },
          { title: "Limitations", content: reply.limitations },
          { title: "Draft notes", content: reply.draftNotes },
        ], spoken.sessionId);
        next.operations.push(operation("witness", payload, spoken, "Witness drafts stored from a fresh session."));
        return refreshNextAction(next);
      });
    });
  }

  private async instructions(role: "oracle" | "architect" | "maker" | "witness", project: Project, text: string): Promise<string> {
    return buildSpiritInstructions(role, project, text, this.options.promptRoot);
  }

  private async claim(actionId: string, payload: object, expectedRevision: number): Promise<Claimed> {
    const loaded = await this.store.load();
    const hash = payloadHash(payload);
    const existing = loaded.state.actions.find((action) => action.id === actionId);
    if (existing) {
      if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
      return { project: loaded.state, duplicate: true };
    }
    if (loaded.state.revision !== expectedRevision) {
      throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
    }
    return { project: loaded.state, duplicate: false };
  }

  private async recordFailure(
    actionId: string,
    payload: object,
    expectedRevision: number,
    role: SpiritRole,
    sessionId: string | null,
    message: string,
  ) {
    const saved = await this.workflow.execute(actionId, payload, expectedRevision, (project) => {
      const next = structuredClone(project);
      const operationId = randomUUID();
      next.operations.push({
        id: operationId,
        kind: role === "witness" ? "witness" : "guide",
        payloadHash: payloadHash(payload),
        nativeSessionId: sessionId,
        nativeMessageId: null,
        status: "FAILED",
        result: message,
      });
      rememberTranscript(next, "system", message);
      return refreshNextAction(next);
    });
    throw new ExperienceFailure(message, "MALFORMED_RESPONSE", 400, true, saved.project.operations.at(-1)?.id ?? null);
  }

  private async recordUncertain(actionId: string, payload: object, expectedRevision: number, intent: string, error: unknown) {
    const message = error instanceof Error ? error.message : "The native spirit could not be reached.";
    const uncertain = /timed out|ECONN|fetch|network|socket|unavailable/i.test(message);
    const saved = await this.workflow.execute(actionId, payload, expectedRevision, (project) => {
      const next = structuredClone(project);
      next.operations.push({
        id: randomUUID(),
        kind: intent === "maker" ? "maker" : intent === "witness" ? "witness" : "guide",
        payloadHash: payloadHash(payload),
        nativeSessionId: null,
        nativeMessageId: null,
        status: uncertain ? "UNKNOWN" : "FAILED",
        result: uncertain
          ? "Disconnected or timed out. Reconcile the native session before any new run."
          : message,
import { sentry } from "@sentry/hono/node";
import { Hono } from "hono";
import { basicAuth } from "hono/basic-auth";
import { streamSSE } from "hono/streaming";
import { z } from "zod";
import { healthSchema, nativeEngineStatusSchema, type NativeEngineStatus } from "../shared/contracts.ts";
import { ExperienceFailure, ExperienceService } from "./experience/service.ts";
import { RevisionConflict } from "./store/atomic-project-store.ts";
import { WorkflowService } from "./workflow/service.ts";
import { approveSection, reviseSection, WorkflowConflict } from "./workflow/transitions.ts";

export type EngineProbe = () => Promise<NativeEngineStatus>;

const actionSchema = z.object({
  actionId: z.string().min(1),
  expectedRevision: z.number().int().nonnegative(),
});
const revisionSchema = actionSchema.extend({ content: z.string().min(1).max(65_536) });
const approvalRequestSchema = actionSchema.extend({
  version: z.number().int().positive(),
  hash: z.string().length(64),
});

const messageSchema = actionSchema.extend({
  intent: z.enum(["clarify", "draft", "question", "witness"]),
  text: z.string().min(1).max(8_000),
});
const approvalKindSchema = z.discriminatedUnion("kind", [
  actionSchema.extend({ kind: z.literal("product") }),
  actionSchema.extend({ kind: z.literal("maker-scope"), statement: z.string().min(8).max(2_000) }),
]);

export interface WorkflowHttpOptions {
  service: WorkflowService;
  sessionToken: string;
  experience?: ExperienceService;
  access?: {
    username: string;
    password: string;
  };
}

export function createApp(probe: EngineProbe, workflow?: WorkflowHttpOptions) {
  const app = new Hono();

  app.use(sentry(app));

  if (workflow?.access) {
    const authenticate = basicAuth({
      username: workflow.access.username,
      password: workflow.access.password,
      realm: "Unfinished Business",
    });
    app.use("*", async (context, next) => {
      if (context.req.path === "/api/health") return next();
      return authenticate(context, next);
    });
  }

  app.get("/api/health", (context) => context.json(healthSchema.parse({
    status: "ok",
    service: "unfinished-business",
  })));

  app.get("/api/engine", async (context) => {
    const status = nativeEngineStatusSchema.parse(await probe());
    return context.json(status, status.available ? 200 : 503);
  });

  if (workflow) {
    app.get("/api/project", async (context) => context.json(await workflow.service.get()));
    app.get("/api/session", (context) => {
      if (workflow.access) return context.json({ token: workflow.sessionToken });
      const host = context.req.header("host") ?? "";
      if (!host.startsWith("127.0.0.1") && !host.startsWith("localhost")) {
        return context.json({ code: "INVALID_ORIGIN", message: "The local session token is only available on loopback.", retryable: false }, 403);
      }
      return context.json({ token: workflow.sessionToken });
    });
    if (workflow.experience) {
      app.get("/api/export", async (context) => context.json(await workflow.experience!.exportApproved()));
    }

    app.use("/api/sections/*", async (context, next) => guard(context, next, workflow.sessionToken));
    app.use("/api/messages", async (context, next) => guard(context, next, workflow.sessionToken));
    app.use("/api/approvals", async (context, next) => guard(context, next, workflow.sessionToken));
    app.use("/api/runs", async (context, next) => guard(context, next, workflow.sessionToken, true));
    app.use("/api/runs/*", async (context, next) => guard(context, next, workflow.sessionToken, true));

    app.post("/api/sections/:id/revisions", async (context) => {
      try {
        const input = revisionSchema.parse(await context.req.json());
        const result = await workflow.service.execute(
          input.actionId,
          input,
          input.expectedRevision,
          (project) => reviseSection(project, context.req.param("id"), input.content),
        );
        return context.json(result);
      } catch (error) {
        if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
          return context.json({ code: "WORKFLOW_CONFLICT", message: error.message }, 409);
        }
        if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: "Invalid revision request." }, 400);
        throw error;
      }
    });

    app.post("/api/sections/:id/approve", async (context) => {
      try {
        const input = approvalRequestSchema.parse(await context.req.json());
        const result = await workflow.service.execute(
          input.actionId,
          input,
          input.expectedRevision,
          (project) => approveSection(project, context.req.param("id"), input.version, input.hash),
        );
        return context.json(result);
      } catch (error) {
        if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
          return context.json({ code: "WORKFLOW_CONFLICT", message: error.message }, 409);
        }
        if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: "Invalid approval request.", retryable: true }, 400);
        throw error;
      }
    });

    app.post("/api/messages", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = messageSchema.parse(await context.req.json());
        const result = await workflow.experience.sendMessage(input.actionId, input.expectedRevision, input.intent, input.text);
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid message.");
      }
    });

    app.post("/api/approvals", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = approvalKindSchema.parse(await context.req.json());
        const statement = input.kind === "maker-scope" ? input.statement : undefined;
        const result = await workflow.experience.approve(input.actionId, input.expectedRevision, input.kind, statement);
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid approval.");
      }
    });

    app.post("/api/runs", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = actionSchema.parse(await context.req.json());
        const result = await workflow.experience.queueMaker(input.actionId, input.expectedRevision);
        return context.json(result, 202);
      } catch (error) {
        return journeyError(context, error, "Invalid Maker run.");
      }
    });

    app.get("/api/runs/:id", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        return context.json(await workflow.experience.getRun(context.req.param("id")));
      } catch (error) {
        return journeyError(context, error, "Invalid Maker run.");
      }
    });

    app.get("/api/runs/:id/events", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const rawCursor = context.req.header("last-event-id") ?? context.req.query("cursor");
        const cursor = rawCursor === undefined ? null : Number(rawCursor);
        const runId = context.req.param("id");
        await workflow.experience.getRun(runId);
        return streamSSE(context, async (stream) => {
          const abort = new AbortController();
          context.req.raw.signal.addEventListener("abort", () => abort.abort(), { once: true });
          stream.onAbort(() => abort.abort());
          for await (const item of workflow.experience!.runEvents(runId, cursor, abort.signal)) {
            if (item.type === "heartbeat") {
              await stream.writeSSE({ event: "heartbeat", data: JSON.stringify({ cursor: item.cursor }) });
            } else if (item.type === "snapshot") {
              await stream.writeSSE({
                event: "snapshot",
                id: String(item.run.lastEventSequence),
                data: JSON.stringify(item),
              });
            } else {
              await stream.writeSSE({
                event: "run-event",
                id: String(item.event.sequence),
                data: JSON.stringify(item),
              });
            }
          }
        });
      } catch (error) {
        return journeyError(context, error, "Invalid Maker event stream.");
      }
    });

    app.post("/api/runs/:id/cancel", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = actionSchema.parse(await context.req.json());
        const result = await workflow.experience.cancel(input.actionId, input.expectedRevision, context.req.param("id"));
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid cancellation.");
      }
    });

    app.post("/api/runs/:id/reconcile", async (context) => {
      if (!workflow.experience) return unavailable(context);
      try {
        const input = actionSchema.parse(await context.req.json());
        const result = await workflow.experience.reconcile(input.actionId, input.expectedRevision, context.req.param("id"));
        return context.json(result);
      } catch (error) {
        return journeyError(context, error, "Invalid reconciliation.");
      }
    });
  }

  return app;
}

async function guard(context: Parameters<Parameters<Hono["use"]>[1]>[0], next: () => Promise<void>, sessionToken: string, protectRead = false) {
  if (context.req.method === "GET" && !protectRead) return next();
  if (context.req.header("x-ub-session-token") !== sessionToken) {
    return context.json({ code: "INVALID_SESSION", message: "Missing or invalid local browser session token.", retryable: false }, 403);
  }
  return next();
}

function unavailable(context: { json: (body: unknown, status?: number) => Response }) {
  return context.json({ code: "ENGINE_UNAVAILABLE", message: "The workshop journey is not configured.", retryable: false }, 503);
}

function journeyError(context: { json: (body: unknown, status?: number) => Response }, error: unknown, validationMessage: string) {
  if (error instanceof ExperienceFailure) {
    return context.json({
      code: error.code,
      message: error.message,
      retryable: error.retryable,
      operationId: error.operationId,
    }, error.status as 400);
  }
  if (error instanceof RevisionConflict || error instanceof WorkflowConflict) {
    return context.json({ code: "WORKFLOW_CONFLICT", message: error.message, retryable: false }, 409);
  }
  if (error instanceof z.ZodError) return context.json({ code: "INVALID_REQUEST", message: validationMessage, retryable: true }, 400);
  throw error;
}
import { createHash, randomUUID } from "node:crypto";
import { z } from "zod";
import { runSchema, type MakerRun } from "../runs/model.ts";

export const sectionStatusSchema = z.enum(["NOT_STARTED", "DRAFT", "APPROVED", "STALE"]);
export const operationStatusSchema = z.enum([
  "QUEUED", "RUNNING", "WAITING_PERMISSION", "SUCCEEDED", "FAILED", "CANCELLED", "UNKNOWN",
]);

export const sectionSchema = z.object({
  id: z.string(),
  title: z.string(),
  order: z.number().int().positive(),
  dependencies: z.array(z.string()),
  content: z.string(),
  version: z.number().int().nonnegative(),
  hash: z.string(),
  status: sectionStatusSchema,
});

export const approvalSchema = z.object({
  id: z.string(),
  sectionId: z.string(),
  version: z.number().int().positive(),
  hash: z.string(),
  approvedAt: z.string(),
  staleReason: z.string().nullable(),
});

export const actionSchema = z.object({
  id: z.string(),
  payloadHash: z.string(),
  resultRevision: z.number().int().nonnegative(),
});

export const operationSchema = z.object({
  id: z.string(),
  kind: z.enum(["guide", "maker", "witness", "check"]).default("guide"),
  payloadHash: z.string(),
  nativeSessionId: z.string().nullable(),
  nativeMessageId: z.string().nullable(),
  status: operationStatusSchema,
  result: z.string().nullable(),
});

export const evidenceSchema = z.object({
  id: z.string(),
  checkId: z.string(),
  nativeResultReference: z.string(),
  testedFingerprint: z.string(),
  result: z.enum(["PASS", "FAIL", "NOT_RUN", "INCONCLUSIVE", "STALE"]),
  observedAt: z.string(),
  limitation: z.string().nullable(),
});

export const productSchema = z.object({
  status: z.enum(["NONE", "PROPOSED", "APPROVED"]).default("NONE"),
  proposal: z.string().nullable().default(null),
  openQuestions: z.array(z.string()).default([]),
});

export const makerScopeSchema = z.object({
  status: z.enum(["NONE", "GRANTED"]).default("NONE"),
  statement: z.string().nullable().default(null),
});

export const transcriptEntrySchema = z.object({
  id: z.string(),
  spirit: z.enum(["user", "oracle", "architect", "maker", "witness", "system"]),
  text: z.string(),
  createdAt: z.string(),
});

export const capabilitySchema = z.object({
  id: z.string(),
  purpose: z.string(),
  nativeMapping: z.string(),
  availability: z.enum(["available", "unavailable", "unknown"]),
  permission: z.string(),
  observedOutcome: z.string().nullable(),
});

export const witnessDraftSchema = z.object({
  id: z.string(),
  title: z.string(),
  content: z.string(),
  nativeSessionId: z.string().nullable(),
});

export const nativeSessionRefSchema = z.object({
  role: z.enum(["oracle", "architect", "maker", "witness"]),
  sessionId: z.string(),
});

const projectFields = {
  id: z.string(),
  revision: z.number().int().nonnegative(),
  workspace: z.string(),
  stage: z.enum(["ORACLE", "ARCHITECT", "MAKER", "WITNESS"]),
  currentSectionId: z.string().nullable(),
  sections: z.array(sectionSchema),
  approvals: z.array(approvalSchema),
  actions: z.array(actionSchema),
  operations: z.array(operationSchema),
  evidence: z.array(evidenceSchema),
  nextAction: z.string(),
  product: productSchema.default({ status: "NONE", proposal: null, openQuestions: [] }),
  makerScope: makerScopeSchema.default({ status: "NONE", statement: null }),
  transcript: z.array(transcriptEntrySchema).default([]),
  capabilities: z.array(capabilitySchema).default([]),
  witnessDrafts: z.array(witnessDraftSchema).default([]),
  nativeSessions: z.array(nativeSessionRefSchema).default([]),
};

export const projectV1Schema = z.object({
  schemaVersion: z.literal(1),
  ...projectFields,
});

export const projectSchema = z.object({
  schemaVersion: z.literal(2),
  ...projectFields,
  runs: z.array(runSchema),
});

export type Project = z.infer<typeof projectSchema>;
export type ProjectV1 = z.infer<typeof projectV1Schema>;
export type PlanSection = z.infer<typeof sectionSchema>;
export type Operation = z.infer<typeof operationSchema>;
export type Capability = z.infer<typeof capabilitySchema>;
export type SpiritRole = "oracle" | "architect" | "maker" | "witness";

const sectionDefinitions = [
  ["control", "Control, product, scope, and acceptance", []],
  ["architecture", "Architecture and contracts", ["control"]],
  ["experience", "Experience", ["control", "architecture"]],
  ["tools", "Tools, access, and cost", ["architecture"]],
  ["verification", "Verification and risks", ["control", "architecture", "tools"]],
  ["phases", "Phases and queue", ["verification"]],
  ["delivery", "Delivery", ["experience", "verification", "phases"]],
  ["readiness", "Execution directive and readiness", ["control", "architecture", "experience", "tools", "verification", "phases", "delivery"]],
] as const;

export function contentHash(content: string): string {
  return createHash("sha256").update(content).digest("hex");
}

export function payloadHash(payload: unknown): string {
  return contentHash(JSON.stringify(payload, Object.keys(payload as object).sort()));
}

export function createProject(workspace: string): Project {
  const sections = sectionDefinitions.map(([id, title, dependencies], index) => ({
    id,
    title,
    order: index + 1,
    dependencies: [...dependencies],
    content: "",
    version: 0,
    hash: contentHash(""),
    status: "NOT_STARTED" as const,
  }));
  return refreshNextAction(projectSchema.parse({
    schemaVersion: 2,
    id: randomUUID(),
    revision: 0,
    workspace,
    stage: "ORACLE",
    currentSectionId: sections[0].id,
    sections,
    approvals: [],
    actions: [],
    operations: [],
    evidence: [],
    nextAction: "Describe an idea and wake the Oracle",
    product: { status: "NONE", proposal: null, openQuestions: [] },
    makerScope: { status: "NONE", statement: null },
    transcript: [],
    capabilities: [
      {
        id: "inspect-changes",
        purpose: "Show the diff from the Maker's native session",
        nativeMapping: "OpenCode session.diff in the isolated demo workspace",
        availability: "unknown",
        permission: "Read-only inspection after a Maker run",
        observedOutcome: null,
      },
      {
        id: "node-check",
        purpose: "Run the approved dependency-free Node test",
        nativeMapping: "bounded node --test in the isolated demo workspace",
        availability: "available",
        permission: "Runs only after an explicit Maker scope grant and a native edit",
        observedOutcome: null,
      },
    ],
    witnessDrafts: [],
    nativeSessions: [],
    runs: [],
  }));
}

export function refreshNextAction(project: Project): Project {
  const current = project.sections.find((section) => section.status !== "APPROVED") ?? null;
  project.currentSectionId = current?.id ?? null;
  if (project.product.status !== "APPROVED") {
    project.stage = "ORACLE";
    project.nextAction = project.product.status === "PROPOSED"
      ? "Approve the Oracle proposal, or ask a question"
      : "Describe an idea and wake the Oracle";
    return project;
  }
  if (current) {
    project.stage = "ARCHITECT";
    project.nextAction = `${current.status === "DRAFT" || current.status === "STALE" ? "Review" : "Draft"} ${current.title}`;
    return project;
  }
  if (project.makerScope.status !== "GRANTED") {
    project.stage = "ARCHITECT";
    project.nextAction = "Grant a separate Maker execution scope";
    return project;
  }
  const makerSucceeded = project.runs.some((run) => run.status === "SUCCEEDED")
    || project.operations.some((operation) => operation.kind === "maker" && operation.status === "SUCCEEDED");
  if (!makerSucceeded) {
    project.stage = "MAKER";
    project.nextAction = "Run the approved Maker unit and inspect the result";
    return project;
  }
  project.stage = "WITNESS";
  project.nextAction = project.witnessDrafts.length
    ? "Review the Witness drafts"
    : "Ask the Witness to review the evidence";
  return project;
}

export function migrateProjectV1(input: unknown): Project {
  const legacy = projectV1Schema.parse(input);
  const epoch = new Date(0).toISOString();
  const runs: MakerRun[] = legacy.operations
    .filter((operation) => operation.kind === "maker")
    .map((operation) => ({
      id: operation.id,
      actionId: `legacy:${operation.id}`,
      payloadHash: operation.payloadHash,
      status: operation.status,
      createdAt: epoch,
      updatedAt: epoch,
      startedAt: ["QUEUED", "CONNECTING"].includes(operation.status) ? null : epoch,
      finishedAt: ["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status) ? epoch : null,
      nativeSessionId: operation.nativeSessionId,
      nativeMessageId: operation.nativeMessageId,
      cancelRequestedAt: null,
      lastEventSequence: 1,
      events: [{
        version: 1,
        id: `legacy-event:${operation.id}`,
        sequence: 1,
        timestamp: epoch,
        category: "recovery",
        summary: `Migrated legacy Maker operation with status ${operation.status}.`,
        metadata: { sourceSchema: 1 },
        evidenceRefs: legacy.evidence
          .filter((evidence) => evidence.nativeResultReference === operation.nativeSessionId)
          .map((evidence) => evidence.id),
      }],
      result: ["SUCCEEDED", "FAILED", "CANCELLED"].includes(operation.status) ? {
        summary: operation.result ?? "The legacy operation had no saved result.",
        diffSummary: operation.result,
        files: [],
        verification: null,
        durationMs: 0,
        model: null,
        usage: null,
        cost: null,
        limitation: "Migrated from schema v1; structured duration, file, model, usage, and verification fields were unavailable.",
      } : null,
      failureCode: operation.status === "FAILED" ? "NATIVE_FAILED" : null,
    }));
  return projectSchema.parse({ ...legacy, schemaVersion: 2, runs });
import { createHash } from "node:crypto";
import { constants } from "node:fs";
import { copyFile, mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { migrateProjectV1, projectSchema, projectV1Schema, type Project } from "../workflow/model.ts";

export class RevisionConflict extends Error {}

export interface LoadResult {
  state: Project;
  source: "current" | "previous";
  corruptPath: string | null;
  migrationBackup: string | null;
}

export class AtomicProjectStore {
  readonly previousPath: string;

  constructor(readonly path: string) {
    this.previousPath = `${path}.previous`;
  }

  private async parse(path: string, migrateCurrent: boolean): Promise<{ state: Project; migrationBackup: string | null }> {
    const source = await readFile(path, "utf8");
    const raw = JSON.parse(source) as { schemaVersion?: unknown };
    if (raw.schemaVersion === 2) return { state: projectSchema.parse(raw), migrationBackup: null };
    if (raw.schemaVersion === 1) {
      projectV1Schema.parse(raw);
      const state = migrateProjectV1(raw);
      const migrationBackup = migrateCurrent ? await this.backupAndReplaceV1(source, state) : null;
      return { state, migrationBackup };
    }
    return { state: projectSchema.parse(raw), migrationBackup: null };
  }

  private async backupAndReplaceV1(source: string, migrated: Project): Promise<string> {
    const checksum = createHash("sha256").update(source).digest("hex");
    const backupPath = `${this.path}.backup-v1-${Date.now()}-${checksum.slice(0, 12)}.json`;
    await copyFile(this.path, backupPath, constants.COPYFILE_EXCL);
    const backup = await readFile(backupPath, "utf8");
    const verifiedChecksum = createHash("sha256").update(backup).digest("hex");
    if (verifiedChecksum !== checksum) throw new Error("State migration backup checksum verification failed.");
    projectV1Schema.parse(JSON.parse(backup));
    await writeFile(`${backupPath}.manifest.json`, `${JSON.stringify({
      sourceSchemaVersion: 1,
      targetSchemaVersion: 2,
      sourcePath: this.path,
      backupPath,
      sha256: checksum,
      createdAt: new Date().toISOString(),
    }, null, 2)}\n`, { flag: "wx" });
    const temporaryPath = `${this.path}.migrate-${process.pid}-${Date.now()}`;
    await writeFile(temporaryPath, `${JSON.stringify(migrated, null, 2)}\n`, { flag: "wx" });
    projectSchema.parse(JSON.parse(await readFile(temporaryPath, "utf8")));
    await rename(temporaryPath, this.path);
    return backupPath;
  }

  async load(): Promise<LoadResult> {
    try {
      const current = await this.parse(this.path, true);
      return { state: current.state, source: "current", corruptPath: null, migrationBackup: current.migrationBackup };
    } catch (currentError) {
      try {
        const previous = await this.parse(this.previousPath, false);
        return { state: previous.state, source: "previous", corruptPath: this.path, migrationBackup: null };
      } catch {
        throw currentError;
      }
    }
  }

  async initialize(project: Project): Promise<void> {
    await mkdir(dirname(this.path), { recursive: true });
    await writeFile(this.path, `${JSON.stringify(project, null, 2)}\n`, { flag: "wx" });
  }

  async save(expectedRevision: number, project: Project): Promise<Project> {
    const loaded = await this.load();
    if (loaded.state.revision !== expectedRevision) {
      throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
    }
    const next = projectSchema.parse({ ...project, revision: expectedRevision + 1 });
    const temporaryPath = `${this.path}.tmp-${process.pid}-${Date.now()}`;
    if (loaded.source === "current") {
      await copyFile(this.path, this.previousPath);
    } else {
      await copyFile(this.path, `${this.path}.corrupt-${Date.now()}`, constants.COPYFILE_EXCL);
    }
    await writeFile(temporaryPath, `${JSON.stringify(next, null, 2)}\n`, { flag: "wx" });
    await rename(temporaryPath, this.path);
    return next;
  }
}

