import { migrateProjectV1, projectSchema, projectV1Schema, type Project } from "../workflow/model.ts";

export class RevisionConflict extends Error {}

export interface LoadResult {
  state: Project;
  source: "current" | "previous";
  corruptPath: string | null;
  migrationBackup: string | null;
}

export class AtomicProjectStore {
  readonly previousPath: string;

  constructor(readonly path: string) {
    this.previousPath = `${path}.previous`;
  }

  private async parse(path: string, migrateCurrent: boolean): Promise<{ state: Project; migrationBackup: string | null }> {
    const source = await readFile(path, "utf8");
    const raw = JSON.parse(source) as { schemaVersion?: unknown };
    if (raw.schemaVersion === 2) return { state: projectSchema.parse(raw), migrationBackup: null };
    if (raw.schemaVersion === 1) {
      projectV1Schema.parse(raw);
      const state = migrateProjectV1(raw);
      const migrationBackup = migrateCurrent ? await this.backupAndReplaceV1(source, state) : null;
      return { state, migrationBackup };
    }
    return { state: projectSchema.parse(raw), migrationBackup: null };
  }

  private async backupAndReplaceV1(source: string, migrated: Project): Promise<string> {
    const checksum = createHash("sha256").update(source).digest("hex");
    const backupPath = `${this.path}.backup-v1-${Date.now()}-${checksum.slice(0, 12)}.json`;
    await copyFile(this.path, backupPath, constants.COPYFILE_EXCL);
    const backup = await readFile(backupPath, "utf8");
    const verifiedChecksum = createHash("sha256").update(backup).digest("hex");
    if (verifiedChecksum !== checksum) throw new Error("State migration backup checksum verification failed.");
    projectV1Schema.parse(JSON.parse(backup));
    await writeFile(`${backupPath}.manifest.json`, `${JSON.stringify({
      sourceSchemaVersion: 1,
      targetSchemaVersion: 2,
      sourcePath: this.path,
      backupPath,
      sha256: checksum,
      createdAt: new Date().toISOString(),
    }, null, 2)}\n`, { flag: "wx" });
    const temporaryPath = `${this.path}.migrate-${process.pid}-${Date.now()}`;
    await writeFile(temporaryPath, `${JSON.stringify(migrated, null, 2)}\n`, { flag: "wx" });
    projectSchema.parse(JSON.parse(await readFile(temporaryPath, "utf8")));
    await rename(temporaryPath, this.path);
    return backupPath;
  }

  async load(): Promise<LoadResult> {
    try {
      const current = await this.parse(this.path, true);
      return { state: current.state, source: "current", corruptPath: null, migrationBackup: current.migrationBackup };
    } catch (currentError) {
      try {
        const previous = await this.parse(this.previousPath, false);
        return { state: previous.state, source: "previous", corruptPath: this.path, migrationBackup: null };
      } catch {
        throw currentError;
      }
    }
  }

  async initialize(project: Project): Promise<void> {
    await mkdir(dirname(this.path), { recursive: true });
    await writeFile(this.path, `${JSON.stringify(project, null, 2)}\n`, { flag: "wx" });
  }

  async save(expectedRevision: number, project: Project): Promise<Project> {
    const loaded = await this.load();
    if (loaded.state.revision !== expectedRevision) {
      throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
    }
    const next = projectSchema.parse({ ...project, revision: expectedRevision + 1 });
    const temporaryPath = `${this.path}.tmp-${process.pid}-${Date.now()}`;
    if (loaded.source === "current") {
      await copyFile(this.path, this.previousPath);
    } else {
      await copyFile(this.path, `${this.path}.corrupt-${Date.now()}`, constants.COPYFILE_EXCL);
    }
    await writeFile(temporaryPath, `${JSON.stringify(next, null, 2)}\n`, { flag: "wx" });
    await rename(temporaryPath, this.path);
    return next;
  }
}

