export class ExperienceFailure extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly status: number,
    readonly retryable: boolean,
    readonly operationId: string | null = null,
  ) {
    super(message);
  }
}

interface Claimed {
  project: Project;
  duplicate: boolean;
}

export class ExperienceService {
  constructor(
    private readonly workflow: WorkflowService,
    private readonly store: AtomicProjectStore,
    private readonly guide: SpiritGuide,
    private readonly coordinator: RunCoordinator,
    private readonly options: { safeDirectory: string; demoWorkspace: string; promptRoot?: string },
  ) {}

  async sendMessage(actionId: string, expectedRevision: number, intent: "clarify" | "draft" | "question" | "witness", text: string) {
    const payload = { intent, text };
    const claimed = await this.claim(actionId, payload, expectedRevision);
    if (claimed.duplicate) return { project: claimed.project, duplicate: true };
    const project = claimed.project;
    try {
      if (intent === "clarify") return await this.clarify(actionId, payload, expectedRevision, project, text);
      if (intent === "draft") return await this.draft(actionId, payload, expectedRevision, project, text);
      if (intent === "question") return await this.question(actionId, payload, expectedRevision, project, text);
      return await this.witness(actionId, payload, expectedRevision, project, text);
    } catch (error) {
      if (error instanceof ExperienceFailure || error instanceof WorkflowConflict || error instanceof RevisionConflict) throw error;
      return this.recordUncertain(actionId, payload, expectedRevision, intent, error);
    }
  }

  async approve(actionId: string, expectedRevision: number, kind: "product" | "maker-scope", statement?: string) {
    const payload = { kind, statement: statement ?? null };
    return this.workflow.execute(actionId, payload, expectedRevision, (project) => {
      if (kind === "product") return approveProduct(project);
      return grantMakerScope(project, statement ?? "");
    });
  }

  async queueMaker(actionId: string, expectedRevision: number) {
    const payload = { intent: "maker" };
    const result = await this.workflow.execute(actionId, payload, expectedRevision, (current) => {
      if (current.makerScope.status !== "GRANTED" || !current.makerScope.statement) {
        throw new ExperienceFailure("Grant a separate Maker scope before a native run.", "MAKER_SCOPE_REQUIRED", 409, false);
      }
      const active = current.runs.find((run) => !terminalRunStatuses.has(run.status));
      if (active) throw new ExperienceFailure(`Maker run ${active.id} is already active.`, "RUN_ALREADY_ACTIVE", 409, false, active.id);
      current.runs.push(createMakerRun(actionId, payloadHash(payload)));
      return refreshNextAction(current);
    });
    const run = result.project.runs.find((item) => item.actionId === actionId);
    if (!run) throw new ExperienceFailure("The saved Maker run could not be found.", "RUN_NOT_FOUND", 500, false);
    if (!result.duplicate) {
      this.coordinator.announce(run);
      this.coordinator.schedule(run.id);
    }
    return { project: result.project, run, duplicate: result.duplicate };
  }

  async cancel(actionId: string, expectedRevision: number, runId: string) {
    const claimed = await this.workflow.execute(actionId, { runId, intent: "cancel" }, expectedRevision, (project) => project);
    if (claimed.duplicate) return { project: claimed.project, run: claimed.project.runs.find((run) => run.id === runId), duplicate: true };
    const project = await this.coordinator.cancel(runId);
    return { project, run: project.runs.find((run) => run.id === runId), duplicate: false };
  }

  async reconcile(actionId: string, expectedRevision: number, runId: string) {
    const claimed = await this.workflow.execute(actionId, { runId, intent: "reconcile" }, expectedRevision, (project) => project);
    if (claimed.duplicate) return { project: claimed.project, run: claimed.project.runs.find((run) => run.id === runId), duplicate: true };
    const project = await this.coordinator.reconcile(runId);
    return { project, run: project.runs.find((run) => run.id === runId), duplicate: false };
  }

  async getRun(runId: string) {
    const project = await this.workflow.get();
    const run = project.runs.find((item) => item.id === runId);
    if (!run) throw new ExperienceFailure("That Maker run does not exist.", "RUN_NOT_FOUND", 404, false);
    return { project, run };
  }

  async *runEvents(runId: string, cursor: number | null, signal: AbortSignal) {
    const { run } = await this.getRun(runId);
    yield* this.coordinator.broker.stream(run, cursor, signal);
  }

  async exportApproved() {
    const project = await this.workflow.get();
    const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
    const plan = unresolved.length
      ? null
      : project.sections
        .toSorted((left, right) => left.order - right.order)
        .map((section) => `## ${section.title}\n\n${section.content}`)
