import assert from "node:assert/strict";
import test from "node:test";
import {
  controlledFailure,
  createMakerRun,
  InvalidRunTransition,
  nativeEventSessionId,
  normalizeNativeEvent,
  transitionRun,
} from "../src/server/runs/model.ts";

test("Maker run transitions reject unsafe state changes", () => {
  const run = createMakerRun("action", "hash", new Date("2026-01-01T00:00:00Z"));
  transitionRun(run, "CONNECTING", { category: "state", summary: "Connecting." });
  transitionRun(run, "RUNNING", { category: "state", summary: "Running." });
  transitionRun(run, "WAITING_PERMISSION", { category: "permission", summary: "Waiting." });
  transitionRun(run, "RUNNING", { category: "permission", summary: "Resumed." });
  transitionRun(run, "VERIFYING", { category: "verification", summary: "Checking." });
  transitionRun(run, "SUCCEEDED", { category: "result", summary: "Done." });
  assert.equal(run.status, "SUCCEEDED");
  assert.equal(run.events.length, 7);
  assert.throws(
    () => transitionRun(run, "RUNNING", { category: "state", summary: "Unsafe retry." }),
    InvalidRunTransition,
  );
});

test("native events keep operational facts and discard secret-bearing payloads", () => {
  const secret = "sk-live-do-not-store";
  const event = {
    type: "session.tool.called",
    data: {
      sessionID: "ses_1",
      executed: true,
      arguments: { authorization: `Bearer ${secret}`, env: { API_KEY: secret } },
      output: secret,
      prompt: secret,
      headers: { cookie: secret },
    },
  };
  assert.equal(nativeEventSessionId(event), "ses_1");
  const normalized = normalizeNativeEvent(event);
  assert.deepEqual(normalized, {
    category: "tool",
    summary: "OpenCode started a tool operation.",
    metadata: { executed: true },
  });
  assert.equal(JSON.stringify(normalized).includes(secret), false);
  assert.equal(normalizeNativeEvent({ type: "session.text.delta", data: { sessionID: "ses_1", text: secret } }), null);
  assert.equal(normalizeNativeEvent({ malformed: true }), null);
});

