import { payloadHash, type Project } from "./model.ts";
import { AtomicProjectStore, RevisionConflict } from "../store/atomic-project-store.ts";

export interface ActionResult {
  project: Project;
  duplicate: boolean;
}

export class WorkflowService {
  private tail: Promise<void> = Promise.resolve();

  constructor(private readonly store: AtomicProjectStore) {}

  async get(): Promise<Project> {
    return this.serialize(async () => (await this.store.load()).state);
  }

  async update(mutation: (project: Project) => Project): Promise<Project> {
    return this.serialize(async () => {
      const loaded = await this.store.load();
      return this.store.save(loaded.state.revision, mutation(loaded.state));
    });
  }

  async execute(
    actionId: string,
    payload: unknown,
    expectedRevision: number,
    mutation: (project: Project) => Project,
  ): Promise<ActionResult> {
    return this.serialize(async () => {
      const loaded = await this.store.load();
      const hash = payloadHash(payload);
      const existing = loaded.state.actions.find((action) => action.id === actionId);
      if (existing) {
        if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
        return { project: loaded.state, duplicate: true };
      }
      if (loaded.state.revision !== expectedRevision) {
        throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
      }
      const next = mutation(loaded.state);
      next.actions.push({ id: actionId, payloadHash: hash, resultRevision: expectedRevision + 1 });
      return { project: await this.store.save(expectedRevision, next), duplicate: false };
    });
  }

  private serialize<T>(work: () => Promise<T>): Promise<T> {
    const result = this.tail.then(work, work);
    this.tail = result.then(() => undefined, () => undefined);
    return result;
  }
}
import * as Sentry from "@sentry/hono/node";
import type { Span } from "@sentry/hono/node";
import { FREE_DEEPSEEK_MODEL } from "../opencode/client.ts";

type SpiritRole = "oracle" | "architect" | "maker" | "witness";

interface OpenCodeResultMetadata {
  sessionId?: string | null;
  messageId?: string | null;
  cost?: number;
}

const pipelineName = "unfinished-business";
const providerName = "opencode";

function baseAttributes(role: SpiritRole, conversationId: string) {
  return {
    "gen_ai.agent.name": role,
    "gen_ai.conversation.id": conversationId,
    "gen_ai.pipeline.name": pipelineName,
    "gen_ai.provider.name": providerName,
    "gen_ai.request.model": FREE_DEEPSEEK_MODEL,
  };
}

function safeSpanError(error: unknown): string {
  const message = error instanceof Error ? error.message : "";
  if (/timed out|timeout|abort/i.test(message)) return "deadline_exceeded";
  if (/ECONN|fetch|network|socket|unavailable/i.test(message)) return "unavailable";
  return "internal_error";
}

function traced<T>(
  options: Parameters<typeof Sentry.startSpan<T>>[0],
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return Sentry.startSpan(options, async (span) => {
    try {
      const result = await work(span);
      span.setStatus({ code: 1 });
      return result;
    } catch (error) {
      span.setStatus({ code: 2, message: safeSpanError(error) });
      throw error;
    }
  });
}

export function traceAgentOperation<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `invoke_agent ${role}`,
    op: "gen_ai.invoke_agent",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "invoke_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceChatOperation<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `chat ${FREE_DEEPSEEK_MODEL}`,
    op: "gen_ai.chat",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "chat",
      "gen_ai.operation.type": "ai_client",
    },
  }, work);
}

export function traceCreateAgent<T>(
  role: SpiritRole,
  conversationId: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `create_agent ${role}`,
    op: "gen_ai.create_agent",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "create_agent",
      "gen_ai.operation.type": "agent",
    },
  }, work);
}

export function traceToolOperation<T>(
  role: SpiritRole,
  conversationId: string,
  toolName: string,
  work: (span: Span) => Promise<T>,
): Promise<T> {
  return traced({
    name: `execute_tool ${toolName}`,
    op: "gen_ai.execute_tool",
    attributes: {
      ...baseAttributes(role, conversationId),
      "gen_ai.operation.name": "execute_tool",
      "gen_ai.operation.type": "tool",
      "gen_ai.tool.name": toolName,
    },
  }, work);
}

export function setOpenCodeResult(span: Span, metadata: OpenCodeResultMetadata): void {
  span.setAttribute("gen_ai.response.model", FREE_DEEPSEEK_MODEL);
  if (metadata.sessionId) span.setAttribute("opencode.session.id", metadata.sessionId);
  if (metadata.messageId) span.setAttribute("gen_ai.response.id", metadata.messageId);
  if (typeof metadata.cost === "number" && Number.isFinite(metadata.cost)) {
    span.setAttribute("gen_ai.cost.total_tokens", metadata.cost);
  }
}
import * as Sentry from "@sentry/hono/node";
import { nodeProfilingIntegration } from "@sentry/profiling-node";

const environment = process.env.SENTRY_ENVIRONMENT ?? process.env.NODE_ENV ?? "development";
const release = process.env.SENTRY_RELEASE
  ?? (process.env.RENDER_GIT_COMMIT ? `unfinished-business@${process.env.RENDER_GIT_COMMIT}` : undefined);
const isProduction = environment === "production";
const tracesSampleRate = sampleRate(process.env.SENTRY_TRACES_SAMPLE_RATE, isProduction ? 0.1 : 1);
const agentTracesSampleRate = sampleRate(process.env.SENTRY_AGENT_TRACES_SAMPLE_RATE, 1);
const profilesSampleRate = sampleRate(process.env.SENTRY_PROFILES_SAMPLE_RATE, isProduction ? 0.1 : 1);

function sampleRate(value: string | undefined, fallback: number): number {
  if (value === undefined || value.trim() === "") return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed >= 0 && parsed <= 1 ? parsed : fallback;
}

Sentry.init({
  dsn: process.env.SENTRY_DSN,
  environment,
  release,
  integrations: [nodeProfilingIntegration()],
  tracesSampler: ({ name, attributes, normalizedRequest, inheritOrSampleWith }) => {
    const requestUrl = normalizedRequest?.url ?? "";
    const isAgentTrace = /\/api\/(?:messages|runs)(?:\/|$)/.test(`${name} ${requestUrl}`)
      || attributes["gen_ai.operation.name"] === "invoke_agent";
    return isAgentTrace ? agentTracesSampleRate : inheritOrSampleWith(tracesSampleRate);
  },
  profileSessionSampleRate: profilesSampleRate,
  profileLifecycle: "trace",
  strictTraceContinuation: true,
  dataCollection: {
    userInfo: false,
    cookies: false,
    httpHeaders: false,
    httpBodies: [],
    urlQueryParams: false,
    graphQL: { document: false, variables: false },
    genAI: { inputs: false, outputs: false },
    mcp: { inputs: false, outputs: false },
    databaseQueryData: false,
    queues: false,
    stackFrameVariables: false,
  },
});
