import { payloadHash, type Project } from "./model.ts";
import { AtomicProjectStore, RevisionConflict } from "../store/atomic-project-store.ts";

export interface ActionResult {
  project: Project;
  duplicate: boolean;
}

export class WorkflowService {
  private tail: Promise<void> = Promise.resolve();

  constructor(private readonly store: AtomicProjectStore) {}

  async get(): Promise<Project> {
    return this.serialize(async () => (await this.store.load()).state);
  }

  async update(mutation: (project: Project) => Project): Promise<Project> {
    return this.serialize(async () => {
      const loaded = await this.store.load();
      return this.store.save(loaded.state.revision, mutation(loaded.state));
    });
  }

  async execute(
    actionId: string,
    payload: unknown,
    expectedRevision: number,
    mutation: (project: Project) => Project,
  ): Promise<ActionResult> {
    return this.serialize(async () => {
      const loaded = await this.store.load();
      const hash = payloadHash(payload);
      const existing = loaded.state.actions.find((action) => action.id === actionId);
      if (existing) {
        if (existing.payloadHash !== hash) throw new RevisionConflict("Action ID was already used with a different payload.");
        return { project: loaded.state, duplicate: true };
      }
      if (loaded.state.revision !== expectedRevision) {
        throw new RevisionConflict(`Expected revision ${expectedRevision}, found ${loaded.state.revision}.`);
      }
      const next = mutation(loaded.state);
      next.actions.push({ id: actionId, payloadHash: hash, resultRevision: expectedRevision + 1 });
      return { project: await this.store.save(expectedRevision, next), duplicate: false };
    });
  }

  private serialize<T>(work: () => Promise<T>): Promise<T> {
    const result = this.tail.then(work, work);
    this.tail = result.then(() => undefined, () => undefined);
    return result;
  }
}
import * as Sentry from "@sentry/hono/node";
import type { Span } from "@sentry/hono/node";
import { FREE_DEEPSEEK_MODEL } from "../opencode/client.ts";

type SpiritRole = "oracle" | "architect" | "maker" | "witness";

interface OpenCodeResultMetadata {
  sessionId?: string | null;
  messageId?: string | null;
  cost?: number;
}

const pipelineName = "unfinished-business";
const providerName = "opencode";

function baseAttributes(role: SpiritRole, conversationId: string) {
  return {
    "gen_ai.agent.name": role,
    "gen_ai.conversation.id": conversationId,
    "gen_ai.pipeline.name": pipelineName,
    "gen_ai.provider.name": providerName,
    "gen_ai.request.model": FREE_DEEPSEEK_MODEL,
  };
}

function safeSpanError(error: unknown): string {
  const message = error instanceof Error ? error.message : "";
  if (/timed out|timeout|abort/i.test(message)) return "deadline_exceeded";
  if (/ECONN|fetch|network|socket|unavailable/i.test(message)) return "unavailable";
  return "internal_error";
}

