  const prepared = await setup();
  await writeFile(join(prepared.directory, "maker.test.mjs"), "import test from 'node:test';\nimport assert from 'node:assert/strict';\ntest('fails', () => assert.equal(1, 2));\n");
  const accepted = await (await postRun(prepared.app)).json();
  await prepared.coordinator.waitForIdle(accepted.run.id);
  const run = (await prepared.store.load()).state.runs[0];
  assert.equal(run.status, "FAILED");
  assert.equal(run.failureCode, "VERIFICATION_FAILED");
  assert.equal(run.result?.files.length, 1);
  assert.equal(run.result?.verification?.status, "FAIL");
});

test("OpenCode boundary failures are stored as controlled outcomes", async (t) => {
  const cases = [
    ["authentication", new Error("401 Unauthorized credential"), "FAILED", "AUTHENTICATION"],
    ["provider limit", new Error("provider quota rate limit"), "FAILED", "PROVIDER_LIMIT"],
    ["missing model", new Error("model not found"), "FAILED", "MISSING_MODEL"],
    ["permission denial", new Error("permission denied"), "FAILED", "PERMISSION_DENIED"],
    ["unavailable", new Error("ECONNREFUSED network unavailable"), "UNKNOWN", null],
  ] as const;
  for (const [name, error, status, code] of cases) {
    await t.test(name, async () => {
      const guide = new FakeGuide();
      guide.createError = error;
      const prepared = await setup(guide);
      const accepted = await (await postRun(prepared.app, `make-${name}`)).json();
      await prepared.coordinator.waitForIdle(accepted.run.id);
      const run = (await prepared.store.load()).state.runs[0];
      assert.equal(run.status, status);
      assert.equal(run.failureCode, code);
      assert.equal(JSON.stringify(run).includes(error.message), false);
    });
  }
});

test("authenticated SSE replays ordered events, resyncs gaps, and closes at terminal state", async () => {
  const prepared = await setup();
  const accepted = await (await postRun(prepared.app)).json();
  await prepared.coordinator.waitForIdle(accepted.run.id);
  const run = (await prepared.store.load()).state.runs[0];

  const denied = await prepared.app.request(`/api/runs/${run.id}/events`);
  assert.equal(denied.status, 403);

  const response = await prepared.app.request(`/api/runs/${run.id}/events?cursor=0`, { headers });
  assert.equal(response.status, 200);
  const body = await response.text();
  const ids = [...body.matchAll(/^id: (\d+)$/gm)].map((match) => Number(match[1]));
  assert.deepEqual(ids, [...ids].sort((left, right) => left - right));
  assert.equal(ids.at(-1), run.lastEventSequence);
  assert.match(body, /event: run-event/);

  const resumed = await prepared.app.request(`/api/runs/${run.id}/events`, {
    headers: { ...headers, "last-event-id": String(run.lastEventSequence) },
  });
  assert.equal(await resumed.text(), "");

  const gap = await prepared.app.request(`/api/runs/${run.id}/events?cursor=999`, { headers });
  assert.match(await gap.text(), /event: snapshot/);
});

