export async function streamRunEvents(
  runId: string,
  cursor: number,
  signal: AbortSignal,
  onItem: (item: RunStreamItem) => void,
): Promise<void> {
  const response = await fetch(`/api/runs/${runId}/events?cursor=${cursor}`, {
    headers: { "x-ub-session-token": await token() },
    signal,
  });
  if (!response.ok || !response.body) {
    const body = await response.json().catch(() => ({})) as { message?: string; code?: string; retryable?: boolean };
    throw new ApiError(body.message ?? "The Run Inspector stream could not be opened.", body.code ?? "RUN_STREAM", Boolean(body.retryable));
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  for (;;) {
    const { value, done } = await reader.read();
    buffer += decoder.decode(value, { stream: !done });
    const frames = buffer.split(/\r?\n\r?\n/);
    buffer = frames.pop() ?? "";
    for (const frame of frames) {
      let event = "message";
      const data: string[] = [];
      for (const line of frame.split(/\r?\n/)) {
        if (line.startsWith("event:")) event = line.slice(6).trim();
        if (line.startsWith("data:")) data.push(line.slice(5).trimStart());
      }
      if (!data.length) continue;
      const parsed = JSON.parse(data.join("\n")) as RunStreamItem;
      if (event === "run-event" || event === "snapshot" || event === "heartbeat") onItem(parsed);
    }
    if (done) return;
  }
}

