  createdAt: string;
  updatedAt: string;
  startedAt: string | null;
  finishedAt: string | null;
  nativeSessionId: string | null;
  nativeMessageId: string | null;
  cancelRequestedAt: string | null;
  lastEventSequence: number;
  events: RunEvent[];
  result: {
    summary: string;
    diffSummary: string | null;
    files: Array<{ path: string; status: "added" | "deleted" | "modified"; additions: number; deletions: number }>;
    verification: { command: "node --test"; status: "PASS" | "FAIL" | "NOT_RUN"; exitCode: number | null; output: string } | null;
    durationMs: number;
    model: { providerID: string; id: string } | null;
    usage: { input: number; output: number; reasoning: number; cacheRead: number; cacheWrite: number } | null;
    cost: number | null;
    limitation: string | null;
  } | null;
  failureCode: "AUTHENTICATION" | "OPENCODE_UNAVAILABLE" | "PROVIDER_LIMIT" | "MISSING_MODEL" | "PERMISSION_DENIED" | "VERIFICATION_FAILED" | "NO_CHANGES" | "NATIVE_FAILED" | "MALFORMED_EVENT" | null;
}

export interface EngineStatus {
  available: boolean;
  serverVersion: string | null;
  modelAvailable: boolean;
  limitation: string | null;
}

export interface ActionResult {
  project: WorkshopProject;
  duplicate: boolean;
}

export interface RunActionResult extends ActionResult {
  run: MakerRun;
}

export type RunStreamItem =
  | { type: "snapshot"; run: MakerRun; events: RunEvent[]; resync: boolean }
  | { type: "event"; run: MakerRun; event: RunEvent }
  | { type: "heartbeat"; cursor: number };

export class ApiError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly retryable: boolean,
  ) {
    super(message);
  }
}

let sessionToken: string | null = null;

async function token(): Promise<string> {
  if (sessionToken) return sessionToken;
  const response = await fetch("/api/session");
  if (!response.ok) throw new ApiError("The local workshop session could not be opened.", "SESSION", true);
  const body = await response.json() as { token: string };
  sessionToken = REDACTED;
  return sessionToken;
}

async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
  const headers: Record<string, string> = {};
  if (init?.body) {
    headers["content-type"] = "application/json";
    headers["x-ub-session-token"] = await token();
  }
  const response = await fetch(path, {
    method: init?.method ?? "GET",
    headers,
    body: init?.body ? JSON.stringify(init.body) : undefined,
  });
  const body = await response.json() as T & { message?: string; code?: string; retryable?: boolean };
  if (!response.ok) {
    throw new ApiError(body.message ?? "The workshop could not complete that action.", body.code ?? "REQUEST_FAILED", Boolean(body.retryable));
  }
  return body;
}

export function loadProject() {
  return request<WorkshopProject>("/api/project");
}

export async function loadEngine(): Promise<EngineStatus> {
  try {
    const response = await fetch("/api/engine");
    const body = await response.json() as Partial<EngineStatus>;
    if (typeof body.available === "boolean") {
      return {
        available: body.available,
        serverVersion: body.serverVersion ?? null,
        modelAvailable: Boolean(body.modelAvailable),
        limitation: body.limitation ?? null,
      };
    }
  } catch {
    // The status below is the visible recovery state.
  }
  return {
    available: false,
    serverVersion: null,
    modelAvailable: false,
    limitation: "OpenCode could not be reached from this workshop.",
  };
}

export function sendMessage(project: WorkshopProject, intent: "clarify" | "draft" | "question" | "witness", text: string) {
  return request<ActionResult>("/api/messages", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, intent, text },
  });
}

export function approveProduct(project: WorkshopProject) {
  return request<ActionResult>("/api/approvals", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, kind: "product" },
  });
}

export function grantScope(project: WorkshopProject, statement: string) {
  return request<ActionResult>("/api/approvals", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, kind: "maker-scope", statement },
  });
}

export function approveSection(project: WorkshopProject, version: number, hash: string, sectionId: string) {
  return request<ActionResult>(`/api/sections/${sectionId}/approve`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, version, hash },
  });
}

export function reviseSection(project: WorkshopProject, sectionId: string, content: string) {
  return request<ActionResult>(`/api/sections/${sectionId}/revisions`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, content },
  });
}

export function runMaker(project: WorkshopProject, actionId = crypto.randomUUID()) {
  return request<RunActionResult>("/api/runs", {
    method: "POST",
    body: { actionId, expectedRevision: project.revision },
  });
}

export function reconcileRun(project: WorkshopProject, operationId: string) {
  return request<RunActionResult>(`/api/runs/${operationId}/reconcile`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision },
  });
}

export function cancelRun(project: WorkshopProject, runId: string) {
  return request<RunActionResult>(`/api/runs/${runId}/cancel`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision },
  });
}

export function loadRun(runId: string) {
  return request<{ project: WorkshopProject; run: MakerRun }>(`/api/runs/${runId}`);
}

export async function streamRunEvents(
  runId: string,
  cursor: number,
  signal: AbortSignal,
  onItem: (item: RunStreamItem) => void,
): Promise<void> {
  const response = await fetch(`/api/runs/${runId}/events?cursor=${cursor}`, {
    headers: { "x-ub-session-token": await token() },
    signal,
  });
  if (!response.ok || !response.body) {
    const body = await response.json().catch(() => ({})) as { message?: string; code?: string; retryable?: boolean };
    throw new ApiError(body.message ?? "The Run Inspector stream could not be opened.", body.code ?? "RUN_STREAM", Boolean(body.retryable));
  }
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  for (;;) {
    const { value, done } = await reader.read();
    buffer += decoder.decode(value, { stream: !done });
    const frames = buffer.split(/\r?\n\r?\n/);
    buffer = frames.pop() ?? "";
    for (const frame of frames) {
      let event = "message";
      const data: string[] = [];
      for (const line of frame.split(/\r?\n/)) {
        if (line.startsWith("event:")) event = line.slice(6).trim();
        if (line.startsWith("data:")) data.push(line.slice(5).trimStart());
      }
      if (!data.length) continue;
      const parsed = JSON.parse(data.join("\n")) as RunStreamItem;
      if (event === "run-event" || event === "snapshot" || event === "heartbeat") onItem(parsed);
    }
    if (done) return;
  }
}

export function loadExport() {
  return request<{ plan: string | null; unresolved: string[]; drafts: Array<{ title: string; content: string }>; limitation: string }>("/api/export");
}

